import { GENRES, EXPERIENCE_SEED, COPY_PACK_SECTIONS, INITIAL_PROJECT } from './data.js';
import { STORAGE_KEY, SETTINGS_KEY, REPO_CATEGORY_LABELS, reviewExperience, recommendGenres, buildGenreAdvice, projectCompleteness, progressFor, localQa, strictScore, scoreLabel, evidenceProfile, escapeHtml, uid, canonicalWorkKey, inferRepoCatalogEntry, mergeRepoCatalog } from './core.js';

const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)], clone=x=>JSON.parse(JSON.stringify(x));
const defaults=window.NARRATIVE_AGENT_DEFAULTS||{};
let state=loadState(),settings=loadSettings(),currentView='dashboard',currentProjectId=state.projects[0]?.id||null,currentProjectTab='bible',portfolioQuery='',portfolioCategory='all',blindSelectedRunId=null;
let busyDepth=0,blindTask=null,blindTaskTicker=null;

function normalizeProject(p){p.chat=Array.isArray(p.chat)?p.chat:[];p.copySections=Array.isArray(p.copySections)?p.copySections:[];p.copyPlan=p.copyPlan||null;p.review=p.review||null;p.portfolioAudit=p.portfolioAudit||null;p.githubReview=p.githubReview||null;p.blindReviews=Array.isArray(p.blindReviews)?p.blindReviews:[];return p;}
function normalizePortfolioScan(scan){if(!scan||typeof scan!=='object')return null;scan.owner=String(scan.owner||'');scan.repoNames=Array.isArray(scan.repoNames)?scan.repoNames:[];scan.batches=Array.isArray(scan.batches)?scan.batches:[];scan.pending=Array.isArray(scan.pending)?scan.pending:[];scan.errors=Array.isArray(scan.errors)?scan.errors:[];scan.synthesisParts=Array.isArray(scan.synthesisParts)?scan.synthesisParts:[];scan.phase=scan.phase||'idle';scan.startedAt=Number(scan.startedAt||Date.now());scan.updatedAt=Number(scan.updatedAt||scan.startedAt);scan.finished=!!scan.finished;scan.message=scan.message||'';scan.summaryMode=scan.summaryMode||'';scan.summaryError=scan.summaryError||'';return scan;}
function loadState(){let v=null;try{v=JSON.parse(localStorage.getItem(STORAGE_KEY));}catch{}if(!v){try{v=JSON.parse(localStorage.getItem('narrative_agent_state_v1'));}catch{}}if(v&&Array.isArray(v.projects)&&Array.isArray(v.experiences)){v.projects.forEach(normalizeProject);const known=new Set(v.experiences.map(x=>x.id));for(const seed of EXPERIENCE_SEED)if(!known.has(seed.id))v.experiences.push(clone(seed));v.portfolioAudit=v.portfolioAudit||null;v.portfolioScan=normalizePortfolioScan(v.portfolioScan);v.repoCache=Array.isArray(v.repoCache)?v.repoCache:[];v.repoCatalog=Array.isArray(v.repoCatalog)?v.repoCatalog:mergeRepoCatalog(v.repoCache,[]);v.version=5;return v;}return{projects:[normalizeProject(clone(INITIAL_PROJECT))],experiences:clone(EXPERIENCE_SEED),portfolioAudit:null,portfolioScan:null,repoCache:[],repoCatalog:[],version:5};}
function loadSettings(){let v={};try{v=JSON.parse(localStorage.getItem(SETTINGS_KEY))||{};}catch{}const mode=['auto','default','fixed'].includes(v.aiMode)?v.aiMode:'auto',provider=['cloudflare','deepseek','doubao'].includes(v.aiProvider)?v.aiProvider:'cloudflare',model=['pro','turbo'].includes(v.aiModel)?v.aiModel:'';return{workerUrl:v.workerUrl??defaults.workerUrl??'',appKey:v.appKey??'',githubOwner:v.githubOwner??defaults.githubOwner??'Mike798-cloud',aiMode:mode,aiProvider:provider,aiModel:model};}
function serializableState(){const c=clone(state);for(const p of c.projects||[])delete p.lastImage;return c;}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(serializableState()));return true;}catch(e){console.warn(e);return false;}}
function saveSettings(){localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings));}
function activeProject(){return state.projects.find(p=>p.id===currentProjectId)||state.projects[0]||null;}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2800);}
function setBusy(v){busyDepth=Math.max(0,busyDepth+(v?1:-1));document.body.classList.toggle('loading',busyDepth>0);}
function modelStrategyLabel(){let s=settings.aiMode==='auto'?'自动路由':settings.aiMode==='fixed'?`固定 ${settings.aiProvider}`:'跟随 Cloudflare 默认';if(settings.aiModel)s+=` · 豆包强档 ${settings.aiModel==='pro'?'Pro':'Turbo'}`;return s;}
function modelStrategyControls(context='main'){return`<div class="organizer-controls ai-strategy"><span class="tiny muted">文本模型策略</span><select data-ai-mode-control="${context}" aria-label="文本模型策略"><option value="auto" ${settings.aiMode==='auto'?'selected':''}>自动按任务难度</option><option value="default" ${settings.aiMode==='default'?'selected':''}>跟随 Cloudflare AI_PROVIDER</option><option value="fixed" ${settings.aiMode==='fixed'?'selected':''}>固定供应商</option></select><select data-ai-provider-control="${context}" aria-label="固定 AI 供应商" ${settings.aiMode==='fixed'?'':'disabled'}><option value="cloudflare" ${settings.aiProvider==='cloudflare'?'selected':''}>Cloudflare</option><option value="deepseek" ${settings.aiProvider==='deepseek'?'selected':''}>DeepSeek</option><option value="doubao" ${settings.aiProvider==='doubao'?'selected':''}>豆包</option></select><select data-ai-model-control="${context}" aria-label="豆包强模型"><option value="" ${!settings.aiModel?'selected':''}>豆包强档：跟随配置</option><option value="pro" ${settings.aiModel==='pro'?'selected':''}>豆包 2.1 Pro</option><option value="turbo" ${settings.aiModel==='turbo'?'selected':''}>豆包 2.1 Turbo</option></select><span class="tiny muted">${escapeHtml(modelStrategyLabel())}</span></div>`;}
function refreshWorkerLabelPending(){const label=$('#workerLabel');if(label)label.textContent=`AI 策略待测试 · ${modelStrategyLabel()}`;}
function bindAiStrategyControls(){$$('[data-ai-mode-control]').forEach(el=>el.onchange=()=>{settings.aiMode=el.value;saveSettings();refreshWorkerLabelPending();render();toast(`文本模型策略：${modelStrategyLabel()}`);});$$('[data-ai-provider-control]').forEach(el=>el.onchange=()=>{settings.aiProvider=el.value;saveSettings();refreshWorkerLabelPending();render();toast(`固定供应商已切换为 ${settings.aiProvider}`);});$$('[data-ai-model-control]').forEach(el=>el.onchange=()=>{settings.aiModel=el.value;saveSettings();refreshWorkerLabelPending();render();toast(`豆包强档：${settings.aiModel==='pro'?'2.1 Pro':settings.aiModel==='turbo'?'2.1 Turbo':'跟随配置'}`);});}
function aiRoutingHeaders(){const h={'X-AI-Mode':settings.aiMode||'auto'};if(settings.aiMode==='fixed')h['X-AI-Provider']=settings.aiProvider||'cloudflare';if(settings.aiModel)h['X-AI-Model']=settings.aiModel;return h;}
function navMeta(){return{dashboard:['WORKSHOP / OVERVIEW','制作总览'],projects:['WORKSHOP / PROJECTS','项目工作台'],genre:['METHOD / GENRE DNA','类型判断'],experience:['KNOWLEDGE / EXPERIENCE','经验库'],portfolio:['ARCHIVE / PORTFOLIO','作品集复盘'],studio:['AGENT / PRODUCTION','AI 制作台'],qa:['REVIEW / QA','独立 QA'],settings:['SYSTEM / SETTINGS','连接与部署']}[currentView];}
function render(){const meta=navMeta();$('#viewEyebrow').textContent=meta[0];$('#viewTitle').textContent=meta[1];$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));$('#content').innerHTML=({dashboard:renderDashboard,projects:renderProjects,genre:renderGenre,experience:renderExperience,portfolio:renderPortfolio,studio:renderStudio,qa:renderQa,settings:renderSettings}[currentView])();bindView();hydrateVisibleImage();}
function genreTags(p){return(p.genres||[]).map(g=>`<span class="tag ${g.score>=60?'hot':''}">${escapeHtml(GENRES.find(x=>x.id===g.id)?.name||g.id)} ${g.score||''}</span>`).join('');}
function issueHtml(i){return`<div class="issue"><div class="sev ${i.severity}">${i.severity}</div><div><strong>${escapeHtml(i.title)}</strong><p>${escapeHtml(i.detail)}</p></div></div>`;}
function progressRow(p,name,field){const pct=progressFor(p,field);return`<div style="margin:10px 0"><div style="display:flex;justify-content:space-between;font-size:11px"><span>${name}</span><span class="mono">${pct}%</span></div><div class="progress"><span style="width:${pct}%"></span></div></div>`;}
function reviewBadge(p){const s=strictScore(p),e=evidenceProfile(p);return s===null?`<span class="tag bad">${e.reviewStale?'评分已过期':'证据制评分：未运行'}</span>`:`<span class="tag ok">独立评分 ${s.toFixed(2)}/10</span>`;}

function renderDashboard(){const p=activeProject(),issues=p?localQa(p):[],coverage=p?projectCompleteness(p):0,s=p?strictScore(p):null;return`<section class="hero"><div><div class="eyebrow">CREATIVE DIRECTOR SYSTEM</div><h3>从一个念头，走到可验证、可发布的网页叙事游戏。</h3><p>Agent 把故事事实层、玩家认知层、页面依赖、谜题、文案、视觉、作品经验与发布 QA 放在同一条流水线上。数字不再奖励“填满字段”，真正 10 分制必须由独立评审给出证据。</p></div><div class="hero-note"><strong>${p?escapeHtml(p.title):'还没有项目'}</strong><span>${p?`验收准备度 ${coverage}% · ${s===null?'尚未独立评分':`独立评分 ${s.toFixed(2)}/10`}`:'先新建项目。'}</span></div></section><div class="metrics"><div class="metric"><div class="num">${state.projects.length}</div><div class="label">项目</div><div class="delta">LOCAL-FIRST</div></div><div class="metric"><div class="num">${state.experiences.length}</div><div class="label">方法论经验</div><div class="delta">先去重再保存</div></div><div class="metric"><div class="num">${state.portfolioAudit?.repoCount||0}</div><div class="label">已复盘公开仓库</div><div class="delta">实际引用链</div></div><div class="metric"><div class="num">${s===null?'—':s.toFixed(2)}</div><div class="label">独立质量评分</div><div class="delta">${s===null?'证据不足不硬算':'只看最终产物'}</div></div></div><section class="section"><div class="section-head"><div><h3>当前项目</h3><p class="lead">验收准备度只表示材料是否足够进入评审，不等于作品质量。</p></div><button class="btn small" data-go="projects">进入工作台</button></div>${p?projectSummary(p):'<div class="empty">没有项目。</div>'}</section><section class="section"><div class="section-head"><div><h3>优先处理</h3><p class="lead">先处理阻断项，再谈 9.5。</p></div><button class="btn small" data-go="qa">完整 QA</button></div>${issues.length?issues.slice(0,6).map(issueHtml).join(''):'<div class="empty">未发现规则级硬伤。</div>'}</section>`;}
function projectSummary(p){return`<div class="grid-2"><div class="panel emphasis"><h4>${escapeHtml(p.title)}</h4><p>${escapeHtml(p.concept)}</p><div>${genreTags(p)} ${reviewBadge(p)}</div></div><div class="panel"><h4>验收准备度</h4>${progressRow(p,'故事圣经','bible')}${progressRow(p,'页面架构','architecture')}${progressRow(p,'谜题','puzzles')}${progressRow(p,'完整文案','copyPack')}${progressRow(p,'视觉','visual')}${progressRow(p,'QA','qa')}</div></div>`;}

function renderProjects(){const p=activeProject();return`<section class="section"><div class="section-head"><div><h3>项目库</h3><p class="lead">项目状态保存在浏览器；生成图片另存 IndexedDB，刷新不会消失。</p></div><button class="btn primary small" id="createProjectInline">新建项目</button></div><div class="project-list">${state.projects.map(x=>`<div class="project-row"><div><div class="project-title">${escapeHtml(x.title)}</div><div class="tiny muted">${escapeHtml(x.concept).slice(0,80)}</div></div><div>${genreTags(x)}</div><div><span class="mono tiny">准备度 ${projectCompleteness(x)}%</span><div class="progress"><span style="width:${projectCompleteness(x)}%"></span></div></div><div class="split-actions"><button class="btn small" data-open-project="${x.id}">打开</button><button class="btn small danger" data-delete-project="${x.id}">删除</button></div></div>`).join('')}</div></section>${p?renderProjectWorkspace(p):''}`;}
function renderProjectWorkspace(p){const tabs=[['bible','故事圣经'],['architecture','页面架构'],['puzzles','谜题图'],['copyPack','完整文案'],['visual','视觉方向'],['imagePrompt','图片设计'],['deploy','发布说明']];const labels={bible:'事实层、人物、知识边界、真实时间线、玩家认知层与最终真相。',architecture:'每个站点/页面的存在理由、进入原因、可见信息、主要出口与跨页关系。',puzzles:'谜题依赖、答案来源、误导、提示层、失败反馈与回报。',copyPack:'长篇文案建议先生成文案矩阵，再逐单元落地并做一致性检查。',visual:'不同载体的年代、机构、材质、排版、美术边界与演出策略。',imagePrompt:'先定义图片世界内来源，再生成镜头、构图与缺陷要求。',deploy:'GitHub Pages / Cloudflare Worker 的发布检查、实际引用文件、移动端和回归测试。'};const taskMap={bible:'story_bible',architecture:'page_architecture',puzzles:'puzzle_design',copyPack:'copy_pack',visual:'visual_direction',imagePrompt:'image_direction',deploy:'release_plan'};const copyTools=currentProjectTab==='copyPack'?`<div class="copy-tools"><button class="btn" id="copyPlanBtn">生成文案矩阵</button>${p.copySections?.length?'<button class="btn" id="copyAllBtn">逐段补齐未完成文案</button>':''}<span class="tiny muted">${p.copySections?.length?`${p.copySections.filter(x=>x.text).length}/${p.copySections.length} 单元已完成`:'尚未建立分段矩阵'}</span></div>${renderCopySections(p)}`:'';return`<section class="section"><div class="section-head"><div><div class="eyebrow">ACTIVE PROJECT</div><h3>${escapeHtml(p.title)}</h3><p class="lead">${escapeHtml(p.concept)}</p></div><div class="split-actions"><button class="btn small" id="editProjectMeta">编辑立项</button><button class="btn small danger" id="deleteProject">删除项目</button></div></div><div class="tabs">${tabs.map(([id,n])=>`<button data-project-tab="${id}" class="${currentProjectTab===id?'active':''}">${n}</button>`).join('')}</div><div class="workspace"><div class="editor field"><label>${labels[currentProjectTab]}</label><textarea id="projectEditor" data-field="${currentProjectTab}" placeholder="可手写，也可以让 AI 生成后继续修改。">${escapeHtml(p[currentProjectTab]||'')}</textarea><div class="split-actions"><button class="btn primary" data-ai-task="${taskMap[currentProjectTab]}">AI 生成 / 深化</button><button class="btn" id="saveProjectField">保存当前内容</button>${currentProjectTab==='imagePrompt'?'<button class="btn" id="generateImageBtn">生成图片</button>':''}</div><div id="imageArea"></div>${copyTools}</div><aside class="side-rail"><div class="rail-block"><h5>类型 DNA</h5>${genreTags(p)}</div><div class="rail-block"><h5>验收准备度</h5><div class="score-ring"><strong>${projectCompleteness(p)}</strong><small>EVIDENCE</small></div><p>不是作品评分。</p></div><div class="rail-block"><h5>独立评分</h5>${reviewBadge(p)}<p>${p.review?.summary?escapeHtml(p.review.summary):'需在 QA 页运行证据制评审。'}</p></div><div class="rail-block"><h5>快速风险</h5>${localQa(p).slice(0,4).map(issueHtml).join('')||'<p>未发现明显结构缺口。</p>'}</div></aside></div></section>`;}
function renderCopySections(p){if(!p.copySections?.length)return'';return`<div class="copy-section-list">${p.copySections.map((s,i)=>`<article class="copy-section"><div><span class="scope">${String(i+1).padStart(2,'0')} / ${escapeHtml(s.surface||'文案')}</span><h4>${escapeHtml(s.title||s.id)}</h4><p>${escapeHtml(s.reveal||'')}</p><small>${s.text?`已生成 ${s.text.length} 字`:`目标约 ${s.targetWords||'—'} 字`}</small></div><button class="btn small ${s.text?'':'primary'}" data-copy-section="${escapeHtml(s.id)}">${s.text?'重写':'生成'}</button></article>`).join('')}</div>`;}

function renderGenre(){const p=activeProject(),concept=p?.concept||'',advice=buildGenreAdvice(recommendGenres(concept));return`<section class="hero"><div><div class="eyebrow">GENRE IS A METHOD, NOT A SKIN</div><h3>类型决定证据和体验，不只是页面颜色。</h3><p>本格、变格、伪网站、密室、社交、档案与 T+P 会改变线索公平性、信息释放、页面结构和交互方式。</p></div><div class="hero-note"><strong>AI 判断可直接写回 DNA</strong><span>不会再只显示一段无法应用的建议。</span></div></section><section class="section"><div class="grid-2"><div class="panel"><h4>项目构想</h4><div class="field"><textarea id="genreConcept">${escapeHtml(concept)}</textarea></div><div class="split-actions"><button class="btn primary" id="genreLocalBtn">本地快速判断</button><button class="btn" id="genreAiBtn">AI 深度判断并应用</button></div></div><div class="panel"><h4>当前建议</h4><div id="genreResults" class="genre-results">${advice.map(genreAdviceHtml).join('')}</div></div></div></section><section class="section"><div class="grid-2">${GENRES.map(g=>`<div class="panel"><h4>${escapeHtml(g.name)}</h4><p><b>核心：</b>${escapeHtml(g.core)}</p><p><b>页面：</b>${escapeHtml(g.style)}</p>${g.avoid.map(x=>`<span class="tag bad">避免 ${escapeHtml(x)}</span>`).join('')}</div>`).join('')}</div></section>`;}
function genreAdviceHtml(g){return`<div class="genre-row"><div class="genre-score">${g.score}<small>%</small></div><div><h4>${escapeHtml(g.name)}</h4><p>${escapeHtml(g.core)}</p><p><b>风格：</b>${escapeHtml(g.style)}</p></div><div>${g.avoid.slice(0,2).map(x=>`<span class="tag bad">${escapeHtml(x)}</span>`).join('')}</div></div>`;}

function renderExperience(){const cats=['全部',...new Set(state.experiences.map(x=>x.category))];return`<section class="hero"><div><div class="eyebrow">LIVING METHOD LIBRARY</div><h3>经验可以增长，但先判断是否重复、是否值得长期保存。</h3><p>AI 深审会返回“合并 / 保存 / 临时 / 拒绝”以及作用范围；不再把所有建议硬编码成项目经验。</p></div><div class="hero-note"><strong>${state.experiences.length} 条经验</strong><span>${state.portfolioAudit?'作品集复盘总结也会作为所有项目的上下文。':'建议先完成一次 GitHub 作品集复盘。'}</span></div></section><section class="section"><div class="grid-2"><div class="panel emphasis"><h4>补充经验</h4><div class="field"><textarea id="experienceInput" placeholder="例如：论坛里的生活帖不能全部为了线索服务，不然一眼就像作者布置的谜题。"></textarea></div><div class="split-actions"><button class="btn primary" id="reviewExperienceBtn">本地评审</button><button class="btn" id="reviewExperienceAiBtn">AI 深审</button></div></div><div class="panel"><h4>评审结果</h4><div id="experienceReview" class="muted tiny">还没有待评审内容。</div></div></div></section><section class="section"><div class="section-head"><div><h3>经验库</h3></div><select id="experienceFilter">${cats.map(c=>`<option>${c}</option>`).join('')}</select></div><div class="experience-list" id="experienceList">${experienceListHtml(state.experiences)}</div></section>`;}
function experienceListHtml(list){return list.map(x=>`<div class="experience-item"><div><span class="scope">${escapeHtml(x.scope)} / ${escapeHtml(x.category)}</span><div class="priority">P${6-(x.priority||3)}</div></div><div><h4>${escapeHtml(x.title)}</h4><p>${escapeHtml(x.body)}</p><div>${(x.genres||[]).map(id=>`<span class="tag">${escapeHtml(GENRES.find(g=>g.id===id)?.name||id)}</span>`).join('')}</div></div><button class="btn small danger" data-delete-exp="${x.id}">删除</button></div>`).join('');}

function portfolioProcessed(scan){const set=new Set();for(const b of scan?.batches||[])for(const n of b.repos||[])set.add(n);for(const x of scan?.pending||[])if(x?.name)set.add(x.name);return set;}
function ensureRepoCatalog(){state.repoCatalog=mergeRepoCatalog(state.repoCache||[],state.repoCatalog||[]);return state.repoCatalog;}
function catalogEntry(repoName){return(state.repoCatalog||[]).find(x=>x.repo===repoName)||null;}
function updateCatalogFromScan(repoName,scan){const repo=(state.repoCache||[]).find(x=>x.name===repoName)||{name:repoName};const old=catalogEntry(repoName);const next=inferRepoCatalogEntry(repo,scan,old);state.repoCatalog=(state.repoCatalog||[]).filter(x=>x.repo!==repoName);state.repoCatalog.push(next);state.repoCatalog.sort((a,b)=>String(b.updated_at||'').localeCompare(String(a.updated_at||'')));}
function repoCategoryOptions(selected){return Object.entries(REPO_CATEGORY_LABELS).map(([id,label])=>`<option value="${id}" ${id===selected?'selected':''}>${escapeHtml(label)}</option>`).join('');}
function catalogCounts(){const c=ensureRepoCatalog(),out={all:c.length,game:0,guide:0,old:0,test:0,tool:0,unknown:0};for(const x of c)out[x.category]=(out[x.category]||0)+1;return out;}
function workGroups(){const groups=new Map();for(const x of ensureRepoCatalog()){if(x.category==='tool')continue;const key=x.workKey||canonicalWorkKey(x.repo)||x.repo.toLowerCase();if(!groups.has(key))groups.set(key,{key,repos:[]});groups.get(key).repos.push(x);}const rank={game:0,unknown:1,guide:2,old:3,test:4};return[...groups.values()].map(g=>{g.repos.sort((a,b)=>(rank[a.category]??9)-(rank[b.category]??9)||String(b.updated_at||'').localeCompare(String(a.updated_at||'')));g.main=g.repos.find(x=>x.category==='game')||g.repos.find(x=>x.category==='unknown')||g.repos[0];g.guides=g.repos.filter(x=>x.category==='guide');g.old=g.repos.filter(x=>x.category==='old');g.tests=g.repos.filter(x=>x.category==='test');g.title=g.main?.signals?.titles?.[0]||g.main?.workTitle||g.main?.repo||g.key;g.linkedProject=state.projects.find(p=>p.githubWorkKey===g.key)||null;return g;}).sort((a,b)=>String(b.main?.updated_at||'').localeCompare(String(a.main?.updated_at||'')));}
function portfolioProgressHtml(){ensureRepoCatalog();const repos=(state.repoCache||[]).filter(r=>!r.archived&&!r.fork&&catalogEntry(r.name)?.category!=='tool'),scan=state.portfolioScan;if(!scan)return`<p>${repos.length?`已读取 ${repos.length} 个公开原创仓库。点击“开始全量扫描”后会自动分批检查。`:'尚未读取仓库列表。'}</p>`;const done=portfolioProcessed(scan).size,total=scan.repoNames?.length||repos.length,repoSet=new Set(scan.repoNames||[]),failed=new Set((scan.errors||[]).filter(x=>repoSet.has(x.repo)).map(x=>x.repo)).size,pct=total?Math.min(100,Math.round(done/total*100)):0;const phase={inspect:'正在检查实际引用链',review:'正在让 AI 总结当前批次',synthesis:'正在分层合并全作品方法论',done:'扫描完成',done_warn:'扫描完成 · AI 总结降级',paused:'扫描已暂停',error:'扫描异常，可继续'}[scan.phase]||'等待继续';return`<div class="scan-status"><div><b>${done}/${total}</b> · ${escapeHtml(phase)}</div><div class="tiny muted">${escapeHtml(scan.message||'')} ${failed?`· ${failed} 个仓库曾失败/超时`:''}</div><div class="progress"><span style="width:${pct}%"></span></div>${scan.updatedAt?`<div class="tiny muted">断点已保存 · ${new Date(scan.updatedAt).toLocaleTimeString()}</div>`:''}</div>`;}
function workGroupHtml(g){
  const main=g.main,repoNames=g.repos.map(x=>x.repo).join('、'),homepage=main?.homepage||(main?.has_pages?`https://${settings.githubOwner.toLowerCase()}.github.io/${main.repo}/`:''),linked=g.linkedProject,gameRepo=g.repos.find(x=>x.category==='game')||null,hasGame=!!gameRepo;
  const uncertain=g.repos.some(x=>x.category==='unknown')||!hasGame;
  const primaryActions=hasGame
    ? `<button class="btn small ${linked?'':'primary'}" data-work-project="${escapeHtml(g.key)}">${linked?'打开项目':'建立项目工作区'}</button><button class="btn small" data-work-analyze="${escapeHtml(g.key)}">深度复盘主仓</button>`
    : `<button class="btn small primary" data-work-assign="${escapeHtml(g.key)}">指定主游戏</button><button class="btn small" data-work-find="${escapeHtml(g.key)}">让 AI 寻找</button>${main?.category==='unknown'?`<button class="btn small" data-work-promote="${escapeHtml(main.repo)}">将候选设为主游戏</button>`:''}`;
  return`<article class="work-card ${uncertain?'uncertain':''}"><div class="work-card-head"><div><span class="scope">${escapeHtml(g.key)}</span><h4>${escapeHtml(g.title)}</h4></div><div>${linked?'<span class="tag ok">已建立项目</span>':''}${!hasGame?'<span class="tag bad">未确认主游戏</span>':g.repos.some(x=>x.category==='unknown')?'<span class="tag bad">含待确认仓库</span>':''}</div></div><p class="tiny muted">${escapeHtml(main?.description||'没有仓库描述')}</p><div class="work-repos"><span class="tag hot">${hasGame?'主':'候选'} ${escapeHtml((gameRepo||main)?.repo||'—')}</span>${g.guides.map(x=>`<span class="tag">攻略 ${escapeHtml(x.repo)}</span>`).join('')}${g.old.map(x=>`<span class="tag">旧版 ${escapeHtml(x.repo)}</span>`).join('')}${g.tests.map(x=>`<span class="tag">测试 ${escapeHtml(x.repo)}</span>`).join('')}</div><div class="work-meta"><span>仓库 ${g.repos.length}</span><span>${main?.signals?`可达文件 ${main.signals.referencedFiles||0}`:'尚未深扫'}</span><span>${main?.updated_at?`更新 ${String(main.updated_at).slice(0,10)}`:''}</span></div>${!hasGame?'<p class="tiny muted">攻略名与游戏名可能不同。先指定主游戏，或让 AI 根据标题、描述、页面内容和更新时间寻找候选；人工确认后会永久锁定。</p>':''}<div class="split-actions">${primaryActions}${main?.repoUrl?`<a class="btn small link-btn" target="_blank" rel="noopener" href="${escapeHtml(main.repoUrl)}">GitHub</a>`:''}${homepage?`<a class="btn small link-btn" target="_blank" rel="noopener" href="${escapeHtml(homepage)}">部署站点</a>`:''}</div><details><summary class="tiny muted">查看关联仓库：${escapeHtml(repoNames)}</summary></details></article>`;}
function repoCatalogTableHtml(){let list=ensureRepoCatalog();const q=portfolioQuery.trim().toLowerCase();if(q)list=list.filter(x=>`${x.repo} ${x.description||''} ${x.workKey||''} ${x.workTitle||''}`.toLowerCase().includes(q));if(portfolioCategory!=='all')list=list.filter(x=>x.category===portfolioCategory);return list.length?`<div class="repo-organizer">${list.map(x=>`<div class="repo-organizer-row"><div><b class="mono">${escapeHtml(x.repo)}</b><p>${escapeHtml(x.description||'')}</p><small>${escapeHtml(x.reason||'')} · ${Math.round(Number(x.confidence||0)*100)}% ${x.manual?'· 人工锁定':x.source==='ai'?'· AI校正':'· 本地初判'}</small></div><select data-repo-category="${escapeHtml(x.repo)}">${repoCategoryOptions(x.category)}</select><div class="field compact-field"><label>作品归组</label><input data-repo-workkey="${escapeHtml(x.repo)}" value="${escapeHtml(x.workKey||'')}" title="相同归组值会被整理为同一部作品"></div><div class="split-actions">${x.manual?`<button class="btn small" data-repo-auto="${escapeHtml(x.repo)}">恢复自动</button>`:''}${x.signals?'<span class="tag ok">已深扫</span>':'<span class="tag">未深扫</span>'}</div></div>`).join('')}</div>`:'<div class="empty">当前筛选没有仓库。</div>';}
function workGroupMatchesCategory(g,category=portfolioCategory){if(category==='all')return true;if(category==='game')return g.repos.some(x=>x.category==='game');if(category==='guide')return g.guides.length>0;if(category==='old')return g.old.length>0;if(category==='test')return g.tests.length>0;if(category==='unknown')return g.repos.some(x=>x.category==='unknown');if(category==='tool')return false;return g.repos.some(x=>x.category===category);}
function filteredWorkGroups(groups=workGroups()){const q=portfolioQuery.trim().toLowerCase();return groups.filter(g=>{if(!workGroupMatchesCategory(g))return false;if(!q)return true;return `${g.title} ${g.key} ${g.repos.map(x=>`${x.repo} ${x.description||''} ${x.workTitle||''}`).join(' ')}`.toLowerCase().includes(q);});}
function portfolioFilterStatusHtml(visible,total){const bits=[];if(portfolioQuery.trim())bits.push(`搜索“${escapeHtml(portfolioQuery.trim())}”`);if(portfolioCategory!=='all')bits.push(REPO_CATEGORY_LABELS[portfolioCategory]||portfolioCategory);const prefix=bits.length?`${bits.join(' · ')}：`:'当前：';return `${prefix}显示 ${visible}/${total} 个作品归组`; }
function portfolioEmptyHtml(){if(portfolioCategory==='tool')return '<div class="empty">工具/服务仓库不会作为“作品卡”展示；请展开下方“逐仓校正分类与归组”查看和修改这些仓库。</div>';return '<div class="empty">当前筛选没有匹配的作品。</div>';}
function bindPortfolioDynamicControls(){$$('[data-repo-category]').forEach(el=>el.onchange=e=>setCatalogField(el.dataset.repoCategory,'category',e.target.value));$$('[data-repo-workkey]').forEach(el=>el.onchange=e=>setCatalogField(el.dataset.repoWorkkey,'workKey',e.target.value));$$('[data-repo-auto]').forEach(el=>el.onclick=()=>unlockCatalogEntry(el.dataset.repoAuto));$$('[data-work-project]').forEach(el=>el.onclick=()=>openOrCreateWorkProject(el.dataset.workProject));$$('[data-work-analyze]').forEach(el=>el.onclick=()=>deepAnalyzeWork(el.dataset.workAnalyze));$$('[data-work-assign]').forEach(el=>el.onclick=()=>showAssignMain(el.dataset.workAssign));$$('[data-work-find]').forEach(el=>el.onclick=()=>findMainGameWithAi(el.dataset.workFind));$$('[data-work-promote]').forEach(el=>el.onclick=()=>promoteRepoToGame(el.dataset.workPromote));}
function refreshPortfolioFilters(){if(currentView!=='portfolio')return;const groups=workGroups(),visible=filteredWorkGroups(groups),grid=$('#portfolioWorkGrid'),repoMount=$('#repoCatalogMount'),status=$('#portfolioFilterStatus');if(grid)grid.innerHTML=visible.map(workGroupHtml).join('')||portfolioEmptyHtml();if(repoMount)repoMount.innerHTML=repoCatalogTableHtml();if(status)status.innerHTML=portfolioFilterStatusHtml(visible.length,groups.length);bindPortfolioDynamicControls();}
function renderPortfolio(){
  ensureRepoCatalog();
  const a=state.portfolioAudit,repos=state.repoCache||[],scan=state.portfolioScan,done=scan?.finished,counts=catalogCounts(),groups=workGroups(),visibleGroups=filteredWorkGroups(groups);
  const summaryStatus=a?.summary?`<span class="tag ${a.summaryMode==='fallback'?'bad':'ok'}">${a.summaryMode==='fallback'?'降级总结':'AI 总结'}</span>`:'';
  const retrySummary=(scan?.batches?.length&&(!a?.summary||a?.summaryMode==='fallback'||scan?.summaryError||scan?.phase==='error'))?'<button class="btn" id="retryPortfolioSummaryBtn">仅重试创作总结</button>':'';
  return`<section class="hero"><div><div class="eyebrow">PORTFOLIO EVIDENCE</div><h3>先把几十个仓库整理成“作品”，再从历史项目里提炼方法。</h3><p>一个仓库不一定等于一部作品：主游戏、攻略、旧版和测试仓库会自动归组；分类只是建议，任何 AI 判断都允许人工纠正并锁定。</p></div><div class="hero-note"><strong>${groups.length} 个作品归组 · ${repos.length} 个仓库</strong><span>${counts.unknown?`${counts.unknown} 个仓库仍待确认`:'仓库分类已无待确认项'}${a?.completedAt?` · 全量复盘 ${new Date(a.completedAt).toLocaleDateString()}`:''}</span></div></section><div class="metrics portfolio-metrics"><div class="metric"><div class="num">${counts.game}</div><div class="label">主游戏候选</div><div class="delta">GAME</div></div><div class="metric"><div class="num">${counts.guide}</div><div class="label">攻略仓库</div><div class="delta">GUIDE</div></div><div class="metric"><div class="num">${counts.old+counts.test}</div><div class="label">旧版 / 测试</div><div class="delta">ARCHIVE</div></div><div class="metric"><div class="num">${counts.unknown}</div><div class="label">待人工确认</div><div class="delta">REVIEW</div></div></div><section class="section"><div class="section-head"><div><h3>仓库扫描</h3><p class="lead">默认排除 fork、archived 与明显工具/服务仓；攻略、旧版、测试会作为所属作品的辅助材料而非独立作品。每批 6 个仓库、最多 3 个并发检查。</p></div><div class="split-actions"><button class="btn" id="loadReposBtn">刷新仓库列表</button><button class="btn primary" id="scanPortfolioBtn">${scan&&!done?'继续扫描':done?'重新扫描全部':'开始全量扫描'}</button>${scan&&!done?'<button class="btn" id="pausePortfolioBtn">本批结束后暂停</button>':''}${scan?'<button class="btn danger" id="resetPortfolioScanBtn">清除断点</button>':''}</div></div><div id="portfolioProgress" class="panel">${portfolioProgressHtml()}</div>${scan?.errors?.length?`<details class="scan-errors"><summary>失败/超时记录 ${scan.errors.length}</summary><div>${scan.errors.slice(-20).map(x=>`<p><b>${escapeHtml(x.repo||'未知仓库')}</b> · ${escapeHtml(x.error||'')}</p>`).join('')}</div></details>`:''}</section><section class="section"><div class="section-head"><div><h3>作品整理</h3><p class="lead">先用本地规则初判，再可让 AI 批量校正；人工修改后会锁定，后续同步不会覆盖你的判断。攻略名与游戏名不一致时可直接“指定主游戏”。</p></div><div class="split-actions"><button class="btn" id="aiCatalogBtn">AI 校正分类</button><button class="btn" id="resetCatalogAutoBtn">重算未锁定项</button></div></div><div class="organizer-controls"><input id="portfolioSearch" value="${escapeHtml(portfolioQuery)}" placeholder="搜索作品或仓库" autocomplete="off"><select id="portfolioCategory"><option value="all">全部分类</option>${Object.entries(REPO_CATEGORY_LABELS).map(([id,label])=>`<option value="${id}" ${portfolioCategory===id?'selected':''}>${escapeHtml(label)}</option>`).join('')}</select><button class="btn small" id="clearPortfolioFiltersBtn" type="button">清除筛选</button><span id="portfolioFilterStatus" class="tiny muted">${portfolioFilterStatusHtml(visibleGroups.length,groups.length)}</span><span id="catalogStatus" class="tiny muted">${counts.unknown?`还有 ${counts.unknown} 个待确认仓库`:'分类已整理'}</span></div><div class="work-grid" id="portfolioWorkGrid">${visibleGroups.map(workGroupHtml).join('')||portfolioEmptyHtml()}</div><details class="repo-details"><summary>逐仓校正分类与归组（${counts.all}）</summary><div id="repoCatalogMount">${repoCatalogTableHtml()}</div></details></section><section class="section"><div class="section-head"><div><h3>作品集方法论总结 ${summaryStatus}</h3><p class="lead">这份总结作为剧情、页面、文案、QA 的共同上下文。最终 AI 总结失败时会先保存可用的降级总结，不再把 66 个仓库扫描结果判成失败；之后可单独重试，不需要重新扫仓库。</p></div>${retrySummary}</div><div class="panel audit-output">${a?.summary?escapeHtml(a.summary):'尚未生成。'}</div>${a?.summaryMode==='fallback'?`<p class="tiny muted">当前为本地降级总结：${escapeHtml(a.summaryError||'AI 总结合并未完成')}。仓库扫描证据仍已保存，可只重试总结。</p>`:''}</section>`;
}


function renderStudio(){
  const p=activeProject(),chat=p?.chat||[];
  return`<section class="section"><div class="section-head"><div><h3>AI 制作台</h3><p class="lead">聊天记录按项目隔离。自动模式会按任务难度选择 fast / standard / strong 路由；也可以临时固定某个供应商。</p></div></div>${modelStrategyControls('studio')}${!p?'<div class="empty">先创建项目。</div>':`<div class="grid-3 studio-grid">
    <button type="button" class="panel studio-card" data-studio-task="project_blueprint"><h4>完整项目策划</h4><p>从定位到发布的制作蓝图。</p><span class="studio-action">运行并写入下方记录 →</span></button>
    <button type="button" class="panel studio-card" id="studioCopyPlan"><h4>文案生产矩阵</h4><p>先拆文案单元，再逐段生成，避免一次硬塞整部作品。</p><span class="studio-action">进入“项目 / 完整文案”生成 →</span></button>
    <button type="button" class="panel studio-card" data-studio-task="virtual_player"><h4>虚拟玩家测试</h4><p>只基于当前可见信息判断卡点。</p><span class="studio-action">运行并写入下方记录 →</span></button>
    <button type="button" class="panel studio-card" id="studioStrictReview"><h4>证据制严格评分</h4><p>材料不足就不评分；评分必须带分项证据。</p><span class="studio-action">转到 QA 并运行评审 →</span></button>
    <button type="button" class="panel studio-card" data-studio-task="anti_ai_review"><h4>AI 味审查</h4><p>文本、UI、美术与人物声线专项检查。</p><span class="studio-action">运行并写入下方记录 →</span></button>
    <button type="button" class="panel studio-card" id="githubAnalyzeCard"><h4>单仓实际引用复盘</h4><p>从入口追踪真实依赖，不随机抽文件。</p><span class="studio-action">选择仓库并复盘 →</span></button>
    <button type="button" class="panel studio-card" id="studioBlindReview"><h4>盲复盘实验</h4><p>隔离事后评价，只看当时主仓实际证据。</p><span class="studio-action">转到 QA 盲复盘 →</span></button>
  </div><div id="studioStatus" class="studio-status ${studioRun?'working':''}" aria-live="polite"><span class="studio-status-dot"></span><span id="studioStatusText">${studioRun?`正在运行「${escapeHtml(studioRun.label)}」…`:'选择上方任务后，这里会显示执行状态；AI 输出会写入下方记录。'}</span><button type="button" class="btn small danger" id="cancelStudioTask" style="display:${studioRun?'inline-block':'none'}">取消当前任务</button></div><div class="section"><div class="console"><div class="messages" id="messages">${chat.length?chat.map(m=>`<div class="message"><div class="role">${escapeHtml(m.role.toUpperCase())}</div><pre>${escapeHtml(m.text)}</pre></div>`).join(''):'<div class="message"><div class="role">SYSTEM</div><pre>选择任务，或直接告诉制作总监要处理什么。</pre></div>'}</div><div class="composer"><textarea id="chatInput" placeholder="告诉制作总监当前问题。"></textarea><button class="btn" id="sendChat" type="button">发送</button></div></div></div>`}</section>`;
}

function fmtDuration(ms){const sec=Math.max(0,Math.round(Number(ms||0)/1000));if(sec<60)return`${sec}s`;const m=Math.floor(sec/60),s=sec%60;return`${m}m ${String(s).padStart(2,'0')}s`;}
const BLIND_MODULES=[
  {id:'flow',label:'玩家流程 / 虚拟玩家'},
  {id:'puzzle',label:'谜题公平性'},
  {id:'authenticity_ai',label:'页面真实性 / AI 味'},
  {id:'narrative_tech',label:'剧情人物 / 技术风险'}
];
function blindTaskStages(verify){return verify?['读取仓库与实际引用','分模块并行盲审','合并模块证据','第二道证据复核','保存测试记录']:['读取仓库与实际引用','分模块并行盲审','合并模块证据','保存测试记录'];}
function blindProgressPct(task){if(!task)return 0;if(task.status==='done')return 100;const stage=task.stage||0;if(stage<=0)return 8;if(stage===1){const mods=task.modules||[],done=mods.filter(x=>x.status==='done'||x.status==='error').length,running=mods.filter(x=>x.status==='running'||x.status==='retrying').length;return Math.min(62,18+Math.round((done+running*.35)/Math.max(1,mods.length)*44));}if(stage===2)return 70;if(task.verify&&stage===3)return 86;return 95;}
function blindEtaSeconds(task){if(!task||task.status==='done'||task.status==='error'||task.status==='cancelled')return null;const el=Date.now()-task.startedAt,pct=blindProgressPct(task);if(pct<=0)return null;return Math.round(el*(100-pct)/Math.max(5,pct)/1000);}
function blindTaskHtml(){if(!blindTask)return'';const stages=blindTask.stages||[],elapsed=Date.now()-blindTask.startedAt,pct=blindProgressPct(blindTask),eta=blindEtaSeconds(blindTask);const rows=stages.map((x,i)=>`<li class="${i<(blindTask.stage||0)?'done':i===(blindTask.stage||0)&&blindTask.status!=='done'?'active':''}"><span>${i<(blindTask.stage||0)?'✓':i+1}</span>${escapeHtml(x)}</li>`).join('');const mods=(blindTask.modules||[]).map(m=>{const status=m.status||'waiting';const icon=status==='done'?'✓':status==='error'?'!':status==='running'||status==='retrying'?'…':'·';let detail='等待';if(status==='running')detail=`初审中 ${fmtDuration(Date.now()-(m.startedAt||Date.now()))}`;else if(status==='retrying')detail=`精简证据重试中 ${fmtDuration(Date.now()-(m.retryStartedAt||Date.now()))}`;else if(status==='done')detail=`完成 ${fmtDuration(m.elapsedMs||0)}${m.fallback?' · 精简重试成功':''}`;else if(status==='error')detail=`未完成 · ${escapeHtml(m.error||'未知错误')}`;const detailBlock=(status==='done'&&m.review)?`<div class="blind-module-detail">${m.review.score!=null?`<b>${Number(m.review.score).toFixed(1)}/10</b>`:''}${m.review.summary?`<span class="tiny muted">${escapeHtml(String(m.review.summary).slice(0,120))}</span>`:''}${(m.review.findings||[]).slice(0,3).map(f=>`<i class="tag ${escapeHtml(f.severity||'P3')}">${escapeHtml(f.severity||'P3')} ${escapeHtml(String(f.title||'').slice(0,40))}</i>`).join('')}</div>`:'';return`<li class="blind-module ${escapeHtml(status)}"><span>${icon}</span><div><b>${escapeHtml(m.label)}</b><small>${detail}</small>${detailBlock}</div></li>`;}).join('');const next=blindTask.waiting?'<button type="button" class="btn small primary" id="blindNextStep">继续：${escapeHtml(blindTask.waiting)}</button>':'';const cancel=blindTask.status==='running'?'<button type="button" class="btn small danger" id="cancelBlindTask">取消本次任务</button>':'';return`<div class="task-progress ${escapeHtml(blindTask.status||'running')}"><div class="task-progress-head"><div><b>${escapeHtml(blindTask.label||'盲复盘')}</b><div class="tiny muted" id="blindTaskElapsed">已运行 ${fmtDuration(elapsed)}${eta!=null?` · 预计剩余 ${fmtDuration(eta*1000)}`:''}${blindTask.message?` · ${escapeHtml(blindTask.message)}`:''}</div></div>${next}${cancel}</div><div class="progress"><i style="width:${pct}%"></i></div><ol>${rows}</ol>${mods?`<ul class="blind-module-list">${mods}</ul>`:''}</div>`;}
function updateBlindTaskUi(){const mount=$('#blindTaskLive');if(!mount)return;mount.innerHTML=blindTaskHtml();const btn=$('#cancelBlindTask');if(btn)btn.onclick=cancelBlindTask;const nx=$('#blindNextStep');if(nx)nx.onclick=continueBlindStep;}
function beginBlindTask(verify,mode='auto',moduleIds=BLIND_MODULES.map(x=>x.id)){if(blindTask?.status==='running')throw new Error('已有盲复盘正在执行，请等待或先取消');const controller=new AbortController();blindTask={controller,verify,mode,moduleIds,stages:blindTaskStages(verify),stage:0,status:'running',startedAt:Date.now(),waiting:'',waitResolve:null,message:'准备读取 GitHub 仓库',label:verify?'严格盲复盘':'快速盲复盘',modules:BLIND_MODULES.filter(x=>moduleIds.includes(x.id)).map(x=>({...x,status:'waiting',startedAt:0,elapsedMs:0,error:''}))};clearInterval(blindTaskTicker);blindTaskTicker=setInterval(updateBlindTaskUi,1000);setBusy(true);updateBlindTaskUi();return blindTask;}
function setBlindTaskStage(stage,message=''){if(!blindTask)return;blindTask.stage=Math.max(0,Math.min(stage,blindTask.stages.length-1));blindTask.message=message;updateBlindTaskUi();}
function setBlindModule(id,status,meta={}){if(!blindTask)return;const m=(blindTask.modules||[]).find(x=>x.id===id);if(!m)return;m.status=status;if(status==='running'&&!m.startedAt)m.startedAt=Date.now();if(status==='retrying')m.retryStartedAt=Date.now();if(meta.elapsedMs!=null)m.elapsedMs=Number(meta.elapsedMs)||0;if(meta.error!=null)m.error=String(meta.error||'');if(meta.fallback!=null)m.fallback=!!meta.fallback;if(meta.review!=null)m.review=meta.review;updateBlindTaskUi();}
function endBlindTask(status,message=''){if(!blindTask)return;blindTask.status=status;blindTask.message=message;if(status==='done')blindTask.stage=blindTask.stages.length;clearInterval(blindTaskTicker);blindTaskTicker=null;setBusy(false);updateBlindTaskUi();const snapshot=blindTask;setTimeout(()=>{if(blindTask===snapshot){blindTask=null;updateBlindTaskUi();}},status==='done'?5500:9000);}
function waitBlindContinue(label){if(!blindTask)return Promise.resolve();blindTask.waiting=label;blindTask.waitResolve=null;updateBlindTaskUi();return new Promise(res=>{blindTask.waitResolve=res;});}
function continueBlindStep(){if(!blindTask||!blindTask.waitResolve)return;const r=blindTask.waitResolve;blindTask.waiting='';blindTask.waitResolve=null;updateBlindTaskUi();r();}
function cancelBlindTask(){if(!blindTask||blindTask.status!=='running')return;blindTask.message='正在取消当前请求…';if(blindTask.waitResolve){const r=blindTask.waitResolve;blindTask.waiting='';blindTask.waitResolve=null;r();}blindTask.controller.abort();updateBlindTaskUi();}
function shouldRetryBlindModuleError(e){const m=String(e?.message||'');return !/(Agent Key|证据快照无效|未知盲复盘模块|操作已取消|额度已用尽|rate.?limit|quota|429|403)/i.test(m);}
function mergeBlindModulesLocal(moduleRuns,evidence,moduleErrors=[]){const ok=moduleRuns.filter(x=>x?.review),sevRank={P0:0,P1:1,P2:2,P3:3};const seen=new Set(),findings=[];for(const x of ok)for(const f of x.review.findings||[]){const key=`${f.category||''}|${String(f.title||'').replace(/[\s\p{P}\p{S}]+/gu,'').toLowerCase()}`;if(!key||seen.has(key))continue;seen.add(key);findings.push(f);}findings.sort((a,b)=>(sevRank[a.severity]??9)-(sevRank[b.severity]??9));const strengths=[],preserve=[];for(const x of ok){strengths.push(...(x.review.strengths||[]).slice(0,3));preserve.push(...(x.review.preserve||[]).slice(0,2));}const scores=ok.map(x=>x.review?.score).filter(x=>x!==null&&x!==undefined&&x!=='').map(Number).filter(Number.isFinite),confidence=ok.length?ok.reduce((n,x)=>n+Number(x.review.confidence||0),0)/ok.length:0;const missing=BLIND_MODULES.filter(m=>!ok.some(x=>x.module===m.id)).map(m=>m.label);const blindSpots=[...new Set(ok.flatMap(x=>x.review.blindSpots||[]))];for(const x of moduleErrors)blindSpots.push(`${x.label}未完成：${x.error}`);if(missing.length)blindSpots.push(`缺少模块：${missing.join('、')}`);const score=ok.length===BLIND_MODULES.length&&!evidence?.truncated&&scores.length===BLIND_MODULES.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length*100)/100:null;return{score,confidence:Math.max(0,Math.min(1,confidence*(ok.length/BLIND_MODULES.length))),summary:ok.map(x=>`【${x.label}】${x.review.summary||''}`).join('\n').slice(0,2200),strengths:strengths.slice(0,10),findings:findings.slice(0,18),preserve:preserve.slice(0,10),blindSpots:blindSpots.slice(0,16)};}
function blindRepoUrl(p){const repo=p?.githubRepos?.main||p?.githubReview?.repo||'';return p?.blindRepoUrl||p?.githubReview?.repoUrl||(repo?`https://github.com/${settings.githubOwner}/${repo}`:'');}
function blindVerdictLabel(v){return({valid:'有效',false_positive:'误报',known:'我原本已知',new_find:'新发现',uncertain:'暂不判断'})[v]||'未判断';}
function blindModelLine(run){const req=run?.requestedRoute||{},actual=run?.model||'—';const mode=req.mode?`${req.mode}${req.provider?` / ${req.provider}`:''}${req.model?` / ${req.model}`:''}`:modelStrategyLabel();return `请求：${mode}；实际：${actual}`;}
function blindRunIncomplete(run){return !!(run&&(run.verifyError||(run.moduleErrors||[]).length||run.mergeError||run.incomplete||((run.moduleSummary||[]).length&& (run.moduleSummary||[]).length<(run.moduleTotal??BLIND_MODULES.length))));}
function blindEmptyMessage(run){if(blindRunIncomplete(run))return '本次检查未完成，不能判定“没有问题”。已保存的只是部分证据结果，请重新运行或换更稳定的模型后复测。';if(run?.zeroChallengeError)return `零结果反证检查未完成：${run.zeroChallengeError}。当前不能把空结果当成可靠结论。`;if(run?.zeroChallenged)return '零结果已额外反证检查；本次没有报告证据充分的问题。';return '本次没有报告证据充分的问题。';}
function blindReviewPanel(p){
  const runs=Array.isArray(p.blindReviews)?p.blindReviews:[];
  const selected=runs.find(x=>x.id===blindSelectedRunId)||runs[0]||null;
  blindSelectedRunId=selected?.id||null;
  const r=selected?.result||{},findings=Array.isArray(r.findings)?r.findings:[],judgments=selected?.judgments||{};
  const counts={valid:0,false_positive:0,known:0,new_find:0,uncertain:0};
  Object.values(judgments).forEach(v=>{if(counts[v]!=null)counts[v]++;});
  const cards=findings.map((f,i)=>{const verdict=judgments[i]||'';const decision=f.decision==='keep'?'建议保留':f.decision==='consider'?'谨慎考虑':'建议修改';return`<article class="evidence-card ${f.decision==='keep'?'keep':''}"><div class="evidence-head"><span class="sev ${escapeHtml(f.severity||'P2')}">${escapeHtml(f.severity||'P2')}</span><span class="tag">${escapeHtml(f.category||'其他')}</span><span class="tag ${f.decision==='keep'?'ok':f.decision==='fix'?'bad':''}">${decision}</span></div><h4>${escapeHtml(f.title||'未命名问题')}</h4><p><b>证据：</b>${escapeHtml(f.evidence||'证据不足')}</p><p><b>影响：</b>${escapeHtml(f.impact||'—')}</p><p><b>建议：</b>${escapeHtml(f.recommendation||'—')}</p><div class="blind-judge"><label>你的判断</label><select data-blind-verdict="${i}" data-blind-run="${escapeHtml(selected?.id||'')}"><option value="" ${!verdict?'selected':''}>未判断</option><option value="valid" ${verdict==='valid'?'selected':''}>有效</option><option value="false_positive" ${verdict==='false_positive'?'selected':''}>误报</option><option value="known" ${verdict==='known'?'selected':''}>我原本已知</option><option value="new_find" ${verdict==='new_find'?'selected':''}>新发现</option><option value="uncertain" ${verdict==='uncertain'?'selected':''}>暂不判断</option></select></div></article>`;}).join('');
  const strengths=(r.strengths||[]).map(x=>`<p class="tiny"><b>${escapeHtml(x.title||'优点')}</b> · ${escapeHtml(x.evidence||'')}</p>`).join('');
  const preserve=(r.preserve||[]).map(x=>`<p class="tiny"><b>${escapeHtml(x.title||'建议保留')}</b> · ${escapeHtml(x.reason||'')}<br><span class="muted">证据：${escapeHtml(x.evidence||'')}</span></p>`).join('');
  const blindSpots=(r.blindSpots||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join('');
  const history=runs.map(x=>`<tr class="${selected?.id===x.id?'selected-row':''}"><td>${new Date(x.createdAt).toLocaleString()}</td><td class="mono">${escapeHtml((x.evidence?.revision||'').slice(0,10)||'—')}</td><td>${x.result?.score==null?'—':Number(x.result.score).toFixed(2)}</td><td>${x.result?.findings?.length||0}</td><td><span class="tiny">${x.verified?'双重复核':'单次'}</span><br><span class="tiny muted">${escapeHtml(blindModelLine(x))}</span></td><td><div class="split-actions compact-actions"><button type="button" class="btn small ${selected?.id===x.id?'primary':''}" data-blind-view="${escapeHtml(x.id)}">${selected?.id===x.id?'正在查看':'查看'}</button><button type="button" class="btn small danger" data-blind-delete="${escapeHtml(x.id)}">删除</button></div></td></tr>`).join('');
  const perf=selected?.performance||null,perfDetail=perf?(perf.modulesMs!=null?` · 总耗时 ${fmtDuration(perf.totalMs||0)}（仓库 ${fmtDuration(perf.prepareMs||0)} / 模块 ${fmtDuration(perf.modulesMs||0)} / 合并 ${fmtDuration(perf.mergeMs||0)}${perf.verifyMs?` / 复核 ${fmtDuration(perf.verifyMs)}`:''}）`:` · 总耗时 ${fmtDuration(perf.totalMs||0)}（仓库 ${fmtDuration(perf.prepareMs||0)} / 初审 ${fmtDuration(perf.evaluateMs||0)}${perf.verifyMs?` / 复核 ${fmtDuration(perf.verifyMs)}`:''}）`):'';
  const moduleNote=selected?.moduleErrors?.length?`<p class="tiny">模块未完成 ${selected.moduleErrors.length} 项：${selected.moduleErrors.map(x=>escapeHtml(x.label||x.module||'未知模块')).join('、')}。最终结果已按现有证据降级处理。</p>`:'';
  const mergeNote=selected?.mergeMode==='local-fallback'?`<p class="tiny">AI 合并未完成，当前记录使用本地证据合并${selected.mergeError?`：${escapeHtml(selected.mergeError)}`:''}。</p>`:'';
  const currentSummary=selected?`<p><b>${selected.result?.score==null?'未评分':`${Number(selected.result.score).toFixed(2)}/10`}</b> · 置信度 ${Math.round(Number(selected.result?.confidence||0)*100)}% · ${selected.result?.findings?.length||0} 个聚类问题</p><p class="tiny muted">${new Date(selected.createdAt).toLocaleString()} · ${escapeHtml(selected.evidence?.repo||'')} · 修订 ${escapeHtml((selected.evidence?.revision||'').slice(0,12)||'—')} · 读取 ${selected.evidence?.filesRead||0} 个文本文件 · 引用 ${selected.evidence?.referenced||0} 个文件 · ${escapeHtml(selected.ruleVersion||'—')}${selected.experienceMode?' · 经验辅助':''} · ${escapeHtml(blindModelLine(selected))}${perfDetail}</p><div class="verdict-strip"><span>有效 ${counts.valid}</span><span>误报 ${counts.false_positive}</span><span>已知 ${counts.known}</span><span>新发现 ${counts.new_find}</span></div>${moduleNote}${mergeNote}${selected.verifyError?`<p class="tiny">二次复核未完成：${escapeHtml(selected.verifyError)}</p>`:''}`:'<p class="muted">还没有盲复盘记录。</p>';
  return`<section class="section blind-lab"><div class="section-head"><div><h3>盲复盘实验</h3><p class="lead">默认只读取当前主游戏仓库的实际引用文件与基础制作宪法；不会把后来玩家反馈、旧评分、项目聊天、作品集总结或项目专属经验喂给评审。勾选“结合经验库”后，经验仅作提示，任何结论仍必须回到实际文件证据。每次测试都会保存在本项目的“盲复盘历史”，可以逐条查看或删除。</p></div></div><div class="grid-2"><div class="panel emphasis"><div class="field"><label>主游戏 GitHub 仓库</label><input id="blindRepoUrl" value="${escapeHtml(blindRepoUrl(p))}" placeholder="https://github.com/${escapeHtml(settings.githubOwner)}/repo"></div><label class="check-row"><input id="blindVerify" type="checkbox" checked> 双重证据复核（第二遍只删误报、合并重复、校正严重度）</label><div class="field"><label>流程模式</label><select id="blindMode"><option value="auto">自动：全流程一次跑完</option><option value="manual">手动：每步完成确认后继续</option></select></div><div class="blind-module-pick"><span class="tiny muted">本次审查模块（可多选）：</span><label class="check-row"><input type="checkbox" data-blind-mod="flow" checked> 玩家流程</label><label class="check-row"><input type="checkbox" data-blind-mod="puzzle" checked> 谜题公平</label><label class="check-row"><input type="checkbox" data-blind-mod="authenticity_ai" checked> 页面真实性</label><label class="check-row"><input type="checkbox" data-blind-mod="narrative_tech" checked> 剧情/技术</label></div><label class="check-row"><input id="blindExperience" type="checkbox"> 结合经验库辅助判断（经验只作提示，结论仍须回到实际文件证据）</label><div class="split-actions"><button class="btn primary" id="blindReviewBtn" type="button">${runs.length?'复测当前版本':'运行盲复盘'}</button>${runs.length?'<button class="btn danger" id="blindClearBtn" type="button">清空全部记录</button>':''}</div><div id="blindTaskLive">${blindTaskHtml()}</div><p class="tiny muted">运行后结果自动保存到当前项目；最多保留最近 20 次。第一轮完成后会先保存草稿，二次复核失败或取消也不会丢失；盲复盘不会冒充真实浏览器点击测试。</p></div><div class="panel"><h4>${selected?'当前查看记录':'当前盲测记录'}${selected&&runs[0]?.id!==selected.id?' · 历史版本':''}</h4>${currentSummary}</div></div>${selected?`<div class="panel audit-output blind-summary" id="blindSelectedSummary"><h4>盲复盘总结</h4><p>${escapeHtml(r.summary||'')}</p>${strengths?`<h5>证据充分的优点</h5>${strengths}`:''}${preserve?`<h5>明确建议保留</h5>${preserve}`:''}${blindSpots?`<h5>本次看不到的内容</h5><ul>${blindSpots}</ul>`:''}</div>${cards?`<div class="evidence-grid">${cards}</div>`:'<div class="empty">${escapeHtml(blindEmptyMessage(selected))}</div>'}`:''}</section><section class="section blind-history-panel"><div class="section-head"><div><h3>盲复盘历史</h3><p class="lead">这里就是测试记录。查看不会重新调用 AI；删除只删除这一条测试，不会删除项目、普通 QA 或作品内容。</p></div><span class="tag">${runs.length} 条</span></div>${runs.length?`<div class="table-scroll"><table><thead><tr><th>时间</th><th>仓库修订</th><th>分数</th><th>问题</th><th>方式 / 模型</th><th>操作</th></tr></thead><tbody>${history}</tbody></table></div>`:'<div class="empty">还没有盲复盘历史。运行一次后会出现在这里。</div>'}</section>`;
}

function renderQa(){const p=activeProject();if(!p)return'<div class="empty">先创建项目。</div>';const issues=localQa(p),s=strictScore(p),e=evidenceProfile(p);const dims=p.review?.dimensions||[];return`<section class="hero"><div><div class="eyebrow">SEPARATE REVIEWER</div><h3>完整度和质量分开。</h3><p>本地只判断“有没有足够证据进入验收”；10 分制由独立评审读取最终材料后生成，并受证据覆盖率和 P0 上限约束。</p></div><div class="hero-note"><strong>${s===null?'未评分':`${s.toFixed(2)} / 10`}</strong><span>验收准备度 ${e.coverage}% · ${p.review?`置信度 ${Math.round((p.review.confidence||0)*100)}%`:'尚未运行独立评审'}</span></div></section>${modelStrategyControls('qa')}${blindReviewPanel(p)}<section class="section"><div class="section-head"><div><h3>本地硬检查</h3></div><div class="split-actions"><button class="btn primary" id="aiQaBtn">运行证据制独立评审</button><button class="btn" id="saveQaBtn">保存本地 QA</button></div></div>${issues.length?issues.map(issueHtml).join(''):'<div class="empty">未发现规则级问题。</div>'}</section><section class="section"><div class="section-head"><div><h3>GitHub Pages 部署巡检</h3><p class="lead">真实请求页面与资源，检查 404、跨页可达性和仓库子路径；不执行浏览器 JS，因此不能替代完整点击回归。</p></div><div class="split-actions"><input id="siteAuditUrl" value="${escapeHtml(p.deployUrl||'')}" placeholder="https://mike798-cloud.github.io/repo/" style="min-width:320px;padding:8px;border:1px solid var(--line);background:var(--paper)"><button class="btn" id="siteAuditBtn">运行部署巡检</button></div></div>${p.siteAudit?`<div class="panel"><p><b>检查 ${p.siteAudit.checked||0} 个 URL，HTML ${p.siteAudit.htmlPages?.length||0} 页，失败 ${p.siteAudit.broken?.length||0} 项。</b></p>${(p.siteAudit.broken||[]).slice(0,12).map(x=>`<p class="tiny">${escapeHtml(String(x.status||0))} · ${escapeHtml(x.url||'')}</p>`).join('')||'<p class="tiny muted">未发现 HTTP 级断链。</p>'}${(p.siteAudit.outsideBase||[]).slice(0,8).map(x=>`<p class="tiny">子路径风险 · ${escapeHtml(x.ref||'')} → ${escapeHtml(x.resolved||'')}</p>`).join('')}${p.siteAudit.interaction?`<div class="interaction-strip"><span>按钮 ${p.siteAudit.interaction.buttons||0}</span><span>点击绑定 ${p.siteAudit.interaction.clickHandlers||0}</span><span>表单 ${p.siteAudit.interaction.forms||0}</span><span>状态写入 ${p.siteAudit.interaction.storageWrites||0}</span><span>根路径特征 ${p.siteAudit.interaction.absoluteRootRefs||0}</span></div>`:''}${(p.siteAudit.warnings||[]).map(x=>`<p class="tiny">静态交互提醒 · ${escapeHtml(x)}</p>`).join('')}</div>`:'<div class="empty">尚未运行部署巡检。</div>'}</section>${p.review?`<section class="section"><h3>独立评分证据</h3><p class="tiny muted">${escapeHtml(p.review.model||'模型未记录')} · ${escapeHtml(p.review.ruleVersion||'规则版本未记录')}</p><div class="review-grid">${dims.map(d=>`<div class="panel"><h4>${escapeHtml(d.name)} · ${d.score==null?'—':`${Number(d.score).toFixed(1)}/10`}</h4><p><b>证据：</b>${escapeHtml(d.evidence||'无')}</p><p><b>问题：</b>${escapeHtml(d.problem||'无')}</p></div>`).join('')}</div><div class="panel audit-output">${escapeHtml(p.review.summary||'')}</div></section>`:''}`;}

function renderSettings(){return`<section class="hero"><div><div class="eyebrow">GITHUB PAGES + CLOUDFLARE WORKER</div><h3>前端公开部署，密钥留在 Worker。</h3><p>GitHub Pages 承载工作台；Worker 负责文本 AI、图片与 GitHub API。模型 Key 只保存在 Cloudflare Secret，浏览器只保存“自动 / 跟随默认 / 固定供应商”的选择。</p></div><div class="hero-note"><strong>离线仍可工作</strong><span>项目、经验、类型初筛、本地 QA 和数据导入导出不依赖 Worker。</span></div></section><section class="section"><div class="grid-2"><div class="panel"><h4>连接设置</h4><div class="form"><div class="field"><label>Cloudflare Worker URL</label><input id="workerUrl" value="${escapeHtml(settings.workerUrl)}" placeholder="https://your-worker.workers.dev"></div><div class="field"><label>Agent Key</label><input id="appKey" type="password" value="${escapeHtml(settings.appKey)}"></div><div class="field"><label>GitHub Owner</label><input id="githubOwner" value="${escapeHtml(settings.githubOwner)}"></div><div class="split-actions"><button class="btn primary" id="saveSettingsBtn">保存并测试</button><button class="btn" id="testWorkerBtn">测试连接</button></div></div></div><div class="panel"><h4>模型策略</h4><p class="tiny muted">自动模式按任务难度路由：仓库分类/经验去重走 FAST，普通创作走 STANDARD，盲复盘/谜题/完整剧情/严格评分走 STRONG。固定模式只影响当前浏览器发出的请求，不修改 Cloudflare 变量。</p>${modelStrategyControls('settings')}<p class="tiny muted">具体 fast / standard / strong 分别使用哪个模型，由 Cloudflare Runtime Variables 配置。</p></div></div><div class="panel" style="margin-top:16px"><h4>数据</h4><p>${state.projects.length} 个项目、${state.experiences.length} 条经验。JSON 导出不包含生成图片二进制。</p><div class="split-actions"><button class="btn" id="exportSettingsData">导出 JSON</button><label class="btn" for="importFile">导入 JSON</label><input id="importFile" type="file" accept="application/json" hidden><button class="btn danger" id="resetAllBtn">恢复初始经验库</button></div></div></section>`;}

function bindView(){
  bindAiStrategyControls();
  $$('[data-go]').forEach(b=>b.onclick=()=>{currentView=b.dataset.go;render();});
  $$('[data-open-project]').forEach(b=>b.onclick=()=>{currentProjectId=b.dataset.openProject;currentProjectTab='bible';blindSelectedRunId=null;render();});
  if($('#createProjectInline'))$('#createProjectInline').onclick=()=>openProjectModal();
  if($('#editProjectMeta'))$('#editProjectMeta').onclick=()=>openProjectModal(activeProject());
  if($('#deleteProject'))$('#deleteProject').onclick=deleteActiveProject;
  $$('[data-project-tab]').forEach(b=>b.onclick=()=>{currentProjectTab=b.dataset.projectTab;render();});
  if($('#saveProjectField'))$('#saveProjectField').onclick=saveProjectEditor;
  $$('[data-ai-task]').forEach(b=>b.onclick=()=>runProjectTask(b.dataset.aiTask));
  if($('#generateImageBtn'))$('#generateImageBtn').onclick=generateImage;
  if($('#copyPlanBtn'))$('#copyPlanBtn').onclick=generateCopyPlan;
  if($('#copyAllBtn'))$('#copyAllBtn').onclick=generateAllCopySections;
  $$('[data-copy-section]').forEach(b=>b.onclick=()=>generateCopySection(b.dataset.copySection));
  if($('#genreLocalBtn'))$('#genreLocalBtn').onclick=runLocalGenre;
  if($('#genreAiBtn'))$('#genreAiBtn').onclick=runAiGenre;
  if($('#reviewExperienceBtn'))$('#reviewExperienceBtn').onclick=runExperienceReview;
  if($('#reviewExperienceAiBtn'))$('#reviewExperienceAiBtn').onclick=runExperienceAiReview;
  if($('#experienceFilter'))$('#experienceFilter').onchange=filterExperiences;
  $$('[data-delete-exp]').forEach(b=>b.onclick=()=>deleteExperience(b.dataset.deleteExp));
  if($('#loadReposBtn'))$('#loadReposBtn').onclick=()=>loadRepoList(true);
  if($('#scanPortfolioBtn'))$('#scanPortfolioBtn').onclick=scanPortfolio;
  if($('#pausePortfolioBtn'))$('#pausePortfolioBtn').onclick=()=>{portfolioStopRequested=true;toast('将在当前批次结束后暂停');};
  if($('#retryPortfolioSummaryBtn'))$('#retryPortfolioSummaryBtn').onclick=retryPortfolioSummary;
  if($('#resetPortfolioScanBtn'))$('#resetPortfolioScanBtn').onclick=resetPortfolioScan;
  if($('#aiCatalogBtn'))$('#aiCatalogBtn').onclick=refineCatalogWithAi;
  if($('#resetCatalogAutoBtn'))$('#resetCatalogAutoBtn').onclick=recomputeCatalog;
  if($('#portfolioSearch'))$('#portfolioSearch').oninput=e=>{portfolioQuery=e.target.value;refreshPortfolioFilters();};
  if($('#portfolioCategory'))$('#portfolioCategory').onchange=e=>{portfolioCategory=e.target.value;refreshPortfolioFilters();};
  if($('#clearPortfolioFiltersBtn'))$('#clearPortfolioFiltersBtn').onclick=()=>{portfolioQuery='';portfolioCategory='all';const input=$('#portfolioSearch'),select=$('#portfolioCategory');if(input)input.value='';if(select)select.value='all';refreshPortfolioFilters();input?.focus();};
  bindPortfolioDynamicControls();
  $$('[data-studio-task]').forEach(b=>b.onclick=()=>runStudioTask(b.dataset.studioTask));
  if($('#studioCopyPlan'))$('#studioCopyPlan').onclick=()=>{toast('正在进入完整文案并生成文案矩阵…');currentView='projects';currentProjectTab='copyPack';render();setTimeout(generateCopyPlan,0);};
  if($('#studioStrictReview'))$('#studioStrictReview').onclick=()=>{toast('正在转到 QA 并运行证据制独立评审…');currentView='qa';render();setTimeout(runAiQa,0);};
  if($('#githubAnalyzeCard'))$('#githubAnalyzeCard').onclick=githubAnalyzePrompt;
  if($('#studioBlindReview'))$('#studioBlindReview').onclick=()=>{currentView='qa';render();setTimeout(()=>{$('#blindRepoUrl')?.scrollIntoView({behavior:'smooth',block:'center'});toast('已进入盲复盘实验');},0);};
  if($('#sendChat'))$('#sendChat').onclick=sendChat;if($('#cancelStudioTask'))$('#cancelStudioTask').onclick=cancelStudioRun;$$('[data-delete-project]').forEach(b=>b.onclick=()=>confirmDeleteProject(b.dataset.deleteProject));
  if($('#blindReviewBtn'))$('#blindReviewBtn').onclick=runBlindReview;
  if($('#blindClearBtn'))$('#blindClearBtn').onclick=clearBlindReviews;
  $$('[data-blind-view]').forEach(el=>el.onclick=()=>viewBlindReview(el.dataset.blindView));
  $$('[data-blind-delete]').forEach(el=>el.onclick=()=>deleteBlindReview(el.dataset.blindDelete));
  $$('[data-blind-verdict]').forEach(el=>el.onchange=e=>setBlindVerdict(e.target.dataset.blindRun,Number(e.target.dataset.blindVerdict),e.target.value));
  if($('#aiQaBtn'))$('#aiQaBtn').onclick=runAiQa;
  if($('#saveQaBtn'))$('#saveQaBtn').onclick=saveLocalQa;
  if($('#siteAuditBtn'))$('#siteAuditBtn').onclick=runSiteAudit;
  if($('#saveSettingsBtn'))$('#saveSettingsBtn').onclick=saveAndTestSettings;
  if($('#testWorkerBtn'))$('#testWorkerBtn').onclick=testWorker;
  if($('#exportSettingsData'))$('#exportSettingsData').onclick=exportData;
  if($('#importFile'))$('#importFile').onchange=importData;
  if($('#resetAllBtn'))$('#resetAllBtn').onclick=resetAll;
}

function saveProjectEditor(){const p=activeProject(),e=$('#projectEditor');if(!p||!e)return;p[e.dataset.field]=e.value;p.updatedAt=Date.now();save();toast('已保存');render();}
function openProjectModal(existing=null){const c=existing||{title:'',concept:'',duration:'50–70 分钟'};showModal(existing?'编辑项目':'新建网页叙事项目',`<div class="form"><div class="field"><label>作品名称</label><input id="modalTitle" value="${escapeHtml(c.title||'')}"></div><div class="field"><label>核心构想</label><textarea id="modalConcept">${escapeHtml(c.concept||'')}</textarea></div><div class="field"><label>目标时长</label><input id="modalDuration" value="${escapeHtml(c.duration||'50–70 分钟')}"></div></div>`,()=>{const title=$('#modalTitle').value.trim()||'未命名项目',concept=$('#modalConcept').value.trim(),duration=$('#modalDuration').value.trim()||'50–70 分钟',genres=recommendGenres(concept).map(x=>({id:x.id,score:x.score}));if(existing){Object.assign(existing,{title,concept,duration,genres,updatedAt:Date.now()});}else{const p=normalizeProject({id:uid('project'),title,concept,duration,genres,stage:'立项',createdAt:Date.now(),bible:'',architecture:'',puzzles:'',copyPack:'',visual:'',imagePrompt:'',qa:'',deploy:'',notes:[]});state.projects.unshift(p);currentProjectId=p.id;}save();closeModal();currentView='projects';render();});}
function showModal(title,body,onSubmit){$('#modalRoot').innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h3>${escapeHtml(title)}</h3><button class="icon-btn" id="modalClose">×</button></div><div class="modal-body">${body}</div><div class="modal-actions"><button class="btn" id="modalCancel">取消</button><button class="btn primary" id="modalSubmit">确认</button></div></div></div>`;$('#modalClose').onclick=closeModal;$('#modalCancel').onclick=closeModal;$('#modalSubmit').onclick=onSubmit;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal();};}
function closeModal(){$('#modalRoot').innerHTML='';}
function confirmDialog(title,message,onOk){showModal(title,`<p>${escapeHtml(String(message)).replace(/\n/g,'<br>')}</p>`,()=>{closeModal();onOk();});}
function confirmDeleteProject(id){const p=state.projects.find(x=>x.id===id);if(!p)return;confirmDialog(`删除项目「${p.title}」？`,p.concept?`${p.concept}\n\n将删除该项目全部本地状态（文案、评审、盲复盘记录）。生成过的图片文件会保留在浏览器 IndexedDB 中。`:'将删除该项目全部本地状态（文案、评审、盲复盘记录）。生成过的图片文件会保留在浏览器 IndexedDB 中。',()=>deleteProjectById(id));}
function deleteProjectById(id){state.projects=state.projects.filter(x=>x.id!==id);if(currentProjectId===id)currentProjectId=null;if(!state.projects.length){state.projects.push(normalizeProject(clone(INITIAL_PROJECT)));currentProjectId=state.projects[0].id;toast('已删除最后一个项目，已创建新的空白项目');}currentProjectTab='bible';blindSelectedRunId=null;save();render();}
function deleteActiveProject(){const p=activeProject();if(!p)return;confirmDeleteProject(p.id);}

function portfolioContext(){return state.portfolioAudit?{repoCount:state.portfolioAudit.repoCount,summary:state.portfolioAudit.summary}:null;}
function taskPayload(p){return{project:p,experiences:relevantExperiences(p),portfolioAudit:portfolioContext()};}
async function studioTaskPayload(task,signal){const p=activeProject(),base=taskPayload(p);if(task==='anti_ai_review'){const repoUrl=blindRepoUrl(p);if(repoUrl){setStudioStatus('正在读取仓库实际页面文件，AI 味审查将基于真实文件…','working');try{const prep=await apiRaw('/api/review/blind/prepare',{repoUrl},'POST',{timeoutMs:180000,signal});if(prep?.snapshot)base.snapshot=prep.snapshot;}catch(e){if(e?.code!=='CANCELLED')toast('仓库取证失败，本次将基于项目文本审查：'+e.message);}}}return base;}
function relevantExperiences(p){const ids=new Set((p.genres||[]).map(x=>x.id));return state.experiences.filter(x=>x.scope==='全局'||x.scope==='项目'||(x.genres||[]).some(g=>ids.has(g))).slice(0,60);}
async function runProjectTask(task){const p=activeProject();if(!p)return;saveProjectEditor();const label=studioTaskLabel(task),signal=startStudioRun(label);toast('正在生成当前项目内容…');setStudioStatus(`正在生成「${label}」…`,'working');startStudioTicker(label,aiCallOptions(task).timeoutMs);try{const r=await callAi(task,taskPayload(p),{signal});const map={story_bible:'bible',page_architecture:'architecture',puzzle_design:'puzzles',copy_pack:'copyPack',visual_direction:'visual',image_direction:'imagePrompt',release_plan:'deploy'};const f=map[task];if(f){p[f]=r.text;p.updatedAt=Date.now();save();render();setStudioStatus(`「${label}」已完成。`,'done');toast('AI 结果已写入项目');}}catch(e){if(e?.code==='CANCELLED'||/取消|已取消/.test(String(e?.message||''))){setStudioStatus(`「${label}」已取消。`,'done');toast('已取消');}else{setStudioStatus(`「${label}」失败：${e.message}`,'error');toast(e.message);}}finally{clearStudioTicker();clearStudioRun(signal);}}

function runLocalGenre(){const c=$('#genreConcept').value,rec=recommendGenres(c),p=activeProject();$('#genreResults').innerHTML=buildGenreAdvice(rec).map(genreAdviceHtml).join('');if(p){p.concept=c;p.genres=rec.map(x=>({id:x.id,score:x.score}));p.updatedAt=Date.now();save();}toast('本地类型 DNA 已应用');}
async function runAiGenre(){const c=$('#genreConcept').value.trim(),p=activeProject();if(!c||!p)return toast('先输入构想');const signal=startStudioRun('AI 类型判断');toast('正在进行 AI 类型判断…');try{const r=await api('/api/genre/review',{concept:c,project:p},'POST',{signal});const genres=(r.result?.genres||[]).filter(x=>GENRES.some(g=>g.id===x.id)).slice(0,3);if(genres.length){p.concept=c;p.genres=genres.map(x=>({id:x.id,score:Number(x.score)||0}));p.updatedAt=Date.now();save();render();toast('AI 类型判断已结构化写回项目');}else toast('AI 没有返回可用的类型判断，请重试');}catch(e){if(e?.code==='CANCELLED'||/取消|已取消/.test(String(e?.message||'')))toast('已取消');else toast(e.message);}finally{clearStudioRun(signal);}}

function runExperienceReview(){const text=$('#experienceInput').value.trim(),r=reviewExperience(text,state.experiences);if(!text)return toast('先写经验');$('#experienceReview').innerHTML=`<p><b>${escapeHtml(r.decision)}</b> · 价值 ${r.worth}/5 · ${escapeHtml(r.scope)}</p><p>${escapeHtml(r.reason)}</p>${r.duplicate?`<p>最相近：${escapeHtml(r.duplicate.item.title)}</p>`:''}<button class="btn small primary" id="acceptExperience">按本地建议保存</button>`;$('#acceptExperience').onclick=()=>applyExperience(text,{action:r.duplicate?'merge':'save',scope:r.scope,worth:r.worth,duplicateId:r.duplicate?.item.id||null,title:text.slice(0,30),mergedRule:text,genres:activeProject()?.genres?.map(x=>x.id)||[]});}
async function runExperienceAiReview(){const text=$('#experienceInput').value.trim();if(!text)return toast('先写经验');const signal=startStudioRun('AI 经验深审');toast('正在判断经验是否重复、是否值得长期保存…');try{const r=await api('/api/experience/review',{text,experiences:state.experiences,project:activeProject()},'POST',{signal});const x=r.review||{};$('#experienceReview').innerHTML=`<p><b>${escapeHtml(x.action||'')}</b> · ${escapeHtml(x.scope||'')} · 价值 ${x.worth||'—'}/5</p><p>${escapeHtml(x.reason||'')}</p><p>${escapeHtml(x.mergedRule||'')}</p><button class="btn small primary" id="applyAiExperience">应用这个判断</button>`;$('#applyAiExperience').onclick=()=>applyExperience(text,x);toast('AI 经验判断已完成，请确认是否应用');}catch(e){if(e?.code==='CANCELLED'||/取消|已取消/.test(String(e?.message||'')))toast('已取消');else toast(e.message);}finally{clearStudioRun(signal);}}
function applyExperience(text,r){if(r.action==='reject'||r.action==='temporary'){toast(r.action==='temporary'?'仅作为本次临时判断，不写入长期经验':'未写入经验库');return;}if(r.action==='merge'&&r.duplicateId){const old=state.experiences.find(x=>x.id===r.duplicateId);if(old){old.body=r.mergedRule||`${old.body}\n${text}`;old.title=r.title||old.title;old.scope=r.scope||old.scope;old.priority=Math.max(old.priority||3,r.worth||3);save();render();toast('已合并到已有经验');return;}}state.experiences.unshift({id:uid('exp'),scope:r.scope||'项目',category:'补充经验',title:r.title||text.slice(0,30),body:r.mergedRule||text,genres:Array.isArray(r.genres)?r.genres:(activeProject()?.genres||[]).map(x=>x.id),priority:r.worth>=4?4:3,createdAt:Date.now()});save();render();toast('经验已保存');}
function filterExperiences(){const c=$('#experienceFilter').value;$('#experienceList').innerHTML=experienceListHtml(c==='全部'?state.experiences:state.experiences.filter(x=>x.category===c));bindView();}
function deleteExperience(id){confirmDialog('删除这条经验？','这条经验将从经验库移除。',()=>{state.experiences=state.experiences.filter(x=>x.id!==id);save();render();});}

async function generateCopyPlan(){const p=activeProject();if(!p)return;saveProjectEditor();const signal=startStudioRun('生成文案矩阵');toast('正在生成文案生产矩阵…');try{const r=await api('/api/copy/plan',taskPayload(p),'POST',{signal});const secs=(r.plan?.sections||[]).map((x,i)=>({...x,id:String(x.id||`section-${i+1}`),text:p.copySections?.find(y=>y.id===String(x.id))?.text||''}));if(!secs.length)throw new Error('文案矩阵为空');p.copyPlan=r.plan;p.copySections=secs;p.updatedAt=Date.now();save();render();toast(`已建立 ${secs.length} 个文案单元`);}catch(e){if(e?.code==='CANCELLED'||/取消|已取消/.test(String(e?.message||'')))toast('已取消');else toast(e.message);}finally{clearStudioRun(signal);}}
async function generateCopySection(id){const p=activeProject(),section=p?.copySections?.find(x=>x.id===id);if(!p||!section)return;const signal=startStudioRun(`生成文案：${section.title}`);toast(`正在生成：${section.title}`);try{const completed=p.copySections.filter(x=>x.text&&x.id!==id).map(x=>({id:x.id,title:x.title,text:x.text.slice(0,2600)}));const slim={...p,lastImage:undefined,chat:undefined,copySections:undefined};const r=await api('/api/copy/section',{project:slim,section,completed,experiences:relevantExperiences(p),portfolioAudit:portfolioContext()},'POST',{signal});section.text=r.text;rebuildCopyPack(p);save();render();toast(`已生成：${section.title}`);}catch(e){if(e?.code==='CANCELLED'){toast('已取消');throw e;}else toast(e.message);}finally{clearStudioRun(signal);}}
async function generateAllCopySections(){const p=activeProject();if(!p?.copySections?.length)return;for(const s of p.copySections.filter(x=>!x.text)){try{await generateCopySection(s.id);}catch(e){if(e?.code==='CANCELLED'){toast('批量生成已取消');break;}throw e;}}toast('未完成文案单元已全部生成');}
function rebuildCopyPack(p){p.copyPack=p.copySections.filter(x=>x.text).map(x=>`## ${x.title}\n\n${x.text}`).join('\n\n');p.updatedAt=Date.now();}

let portfolioStopRequested=false;
function setCatalogField(repo,field,value){const x=catalogEntry(repo);if(!x)return;if(field==='category'&&!REPO_CATEGORY_LABELS[value])return;if(field==='workKey'){value=canonicalWorkKey(value)||canonicalWorkKey(repo)||repo.toLowerCase();}x[field]=value;x.manual=true;x.source='manual';x.confidence=1;x.reason='人工校正并锁定';save();render();toast('已保存人工分类，后续同步不会覆盖');}
function unlockCatalogEntry(repo){const x=catalogEntry(repo),meta=(state.repoCache||[]).find(r=>r.name===repo);if(!x||!meta)return;const next=inferRepoCatalogEntry(meta,x.signals?{signals:x.signals,entries:x.entries||[]}:null,null);Object.assign(x,next,{manual:false,source:'heuristic'});save();render();toast('已恢复自动判断');}
function recomputeCatalog(){ensureRepoCatalog();state.repoCatalog=state.repoCatalog.map(x=>{if(x.manual)return x;const meta=(state.repoCache||[]).find(r=>r.name===x.repo)||x;return inferRepoCatalogEntry(meta,x.signals?{signals:x.signals,entries:x.entries||[]}:null,null);});save();render();toast('未锁定仓库已重新执行本地分类');}
function mainCandidateEntries(sourceKey=''){const own=new Set((workGroups().find(g=>g.key===sourceKey)?.repos||[]).map(x=>x.repo));return ensureRepoCatalog().filter(x=>!own.has(x.repo)&&(x.category==='game'||x.category==='unknown')).sort((a,b)=>(a.category==='game'?0:1)-(b.category==='game'?0:1)||String(b.updated_at||'').localeCompare(String(a.updated_at||'')));}
function migrateLinkedWorkKey(oldKey,newKey,targetRepo){for(const p of state.projects||[]){if(p.githubWorkKey!==oldKey)continue;p.githubWorkKey=newKey;p.githubRepos=p.githubRepos||{};p.githubRepos.main=targetRepo;p.updatedAt=Date.now();}}
function assignGroupToMain(workKey,targetRepo){const group=workGroups().find(g=>g.key===workKey),target=catalogEntry(targetRepo);if(!group||!target)return toast('找不到待关联作品或主游戏仓库');const targetKey=target.workKey||canonicalWorkKey(target.repo)||target.repo.toLowerCase();if(target.category==='unknown'){target.category='game';target.manual=true;target.source='manual';target.confidence=1;target.reason='人工确认为主游戏';}target.workKey=targetKey;for(const x of group.repos){if(x.repo===target.repo)continue;x.workKey=targetKey;x.manual=true;x.source='manual';x.confidence=1;x.reason=`人工关联到主游戏 ${target.repo}`;}migrateLinkedWorkKey(workKey,targetKey,target.repo);save();closeModal();render();toast(`已关联到主游戏 ${target.repo}，人工判断已锁定`);}
function showAssignMain(workKey){const group=workGroups().find(g=>g.key===workKey),candidates=mainCandidateEntries(workKey);if(!group)return;if(!candidates.length)return toast('目前没有其他主游戏/待确认仓库可选；可先刷新仓库或在逐仓列表中把主仓标记为“游戏”');const opts=candidates.map(x=>`<option value="${escapeHtml(x.repo)}">${escapeHtml(x.repo)}${x.signals?.titles?.[0]?` ｜ ${escapeHtml(x.signals.titles[0])}`:''}${x.category==='unknown'?' ｜ 待确认':''}</option>`).join('');showModal('指定主游戏',`<p class="tiny muted">将「${escapeHtml(group.repos.map(x=>x.repo).join('、'))}」关联到真实主游戏。确认后会人工锁定，后续同步和 AI 分类不会覆盖。</p><div class="field"><label>主游戏仓库</label><select id="mainRepoSelect">${opts}</select></div>`,()=>assignGroupToMain(workKey,$('#mainRepoSelect').value));}
function promoteRepoToGame(repo){const x=catalogEntry(repo);if(!x)return;x.category='game';x.workKey=x.workKey||canonicalWorkKey(repo)||repo.toLowerCase();x.manual=true;x.source='manual';x.confidence=1;x.reason='人工确认为主游戏';save();render();toast(`${repo} 已设为主游戏并锁定`);}
async function findMainGameWithAi(workKey){const group=workGroups().find(g=>g.key===workKey),candidates=mainCandidateEntries(workKey);if(!group||!candidates.length)return toast('没有可供匹配的主游戏候选');toast('AI 正在寻找可能的主游戏候选…');setBusy(true);try{const slim=x=>({repo:x.repo,description:x.description,updated_at:x.updated_at,homepage:x.homepage,category:x.category,workKey:x.workKey,workTitle:x.workTitle,titles:(x.signals?.titles||[]).slice(0,6),entries:(x.entries||[]).slice(0,6),signals:x.signals?{htmlFiles:x.signals.htmlFiles,reachableTextFiles:x.signals.reachableTextFiles,referencedFiles:x.signals.referencedFiles}:null});const r=await apiRaw('/api/portfolio/match-main',{owner:settings.githubOwner,source:group.repos.map(slim),candidates:candidates.slice(0,60).map(slim)},'POST',{timeoutMs:300000});const matches=(r.matches||[]).filter(x=>catalogEntry(x.repo)).slice(0,6);if(!matches.length)throw new Error('AI 没有找到可信候选，请手动指定');const rows=matches.map((m,i)=>`<label class="panel" style="display:block;margin:8px 0;cursor:pointer"><input type="radio" name="mainMatch" value="${escapeHtml(m.repo)}" ${i===0?'checked':''}> <b>${escapeHtml(m.repo)}</b> · ${Math.round(Number(m.confidence||0)*100)}%<br><span class="tiny muted">${escapeHtml(m.reason||'')}</span>${m.evidence?`<br><span class="tiny muted">证据：${escapeHtml(m.evidence)}</span>`:''}</label>`).join('');showModal('AI 寻找主游戏',`<p class="tiny muted">这里只是匹配置信度，不是作品评分。请人工确认后再关联。</p>${rows}`,()=>{const selected=$('input[name="mainMatch"]:checked')?.value;if(selected)assignGroupToMain(workKey,selected);});}catch(e){toast(`主游戏匹配失败：${e.message}`);}finally{setBusy(false);}}
async function refineCatalogWithAi(){const items=ensureRepoCatalog().filter(x=>!x.manual);if(!items.length)return toast('没有可由 AI 校正的仓库');setBusy(true);try{for(let i=0;i<items.length;i+=18){const batch=items.slice(i,i+18),status=$('#catalogStatus');if(status)status.textContent=`AI 正在校正 ${i+1}-${Math.min(items.length,i+batch.length)}/${items.length}…`;const payload=batch.map(x=>({repo:x.repo,description:x.description,homepage:x.homepage,language:x.language,currentCategory:x.category,currentWorkKey:x.workKey,signals:x.signals?{htmlFiles:x.signals.htmlFiles,imageFiles:x.signals.imageFiles,reachableTextFiles:x.signals.reachableTextFiles,hasPayment:x.signals.hasPayment,titles:x.signals.titles,interaction:x.signals.interaction}:null,entries:(x.entries||[]).slice(0,8)}));const r=await apiRaw('/api/portfolio/catalog',{owner:settings.githubOwner,items:payload},'POST',{timeoutMs:300000});for(const j of r.items||[]){const x=catalogEntry(j.repo);if(!x||x.manual||!REPO_CATEGORY_LABELS[j.category])continue;x.category=j.category;x.workKey=canonicalWorkKey(j.workKey||x.workKey||x.repo)||canonicalWorkKey(x.repo);x.workTitle=String(j.workTitle||x.workTitle||x.repo).slice(0,120);x.confidence=Math.max(0,Math.min(1,Number(j.confidence)||.6));x.reason=String(j.reason||'AI 分类校正').slice(0,260);x.source='ai';}if(!save())throw new Error('本地存储空间不足，无法保存分类结果');}render();toast('AI 分类与作品归组校正完成');}catch(e){toast(`AI 分类未完成：${e.message}`);}finally{setBusy(false);}}
function ensureWorkProject(workKey){const group=workGroups().find(g=>g.key===workKey);if(!group)return null;const confirmed=group.repos.find(x=>x.category==='game');if(!confirmed){toast('请先指定并确认主游戏，再建立项目工作区');return null;}if(group.linkedProject)return group.linkedProject;const main=confirmed,concept=main.description||`从 GitHub 仓库 ${main.repo||workKey} 导入的网页作品。`;const p=normalizeProject({...clone(INITIAL_PROJECT),id:uid('project'),title:group.title||main.repo||workKey,concept,createdAt:Date.now(),updatedAt:Date.now(),stage:(main.homepage||main.has_pages)?'已发布':'GitHub 导入',genres:recommendGenres(`${group.title} ${concept}`).map(x=>({id:x.id,score:x.score})),githubWorkKey:group.key,githubRepos:{main:main.repo||'',guides:group.guides.map(x=>x.repo),old:group.old.map(x=>x.repo),tests:group.tests.map(x=>x.repo)},deployUrl:main.homepage||(main.has_pages?`https://${settings.githubOwner.toLowerCase()}.github.io/${main.repo}/`:''),portfolioAudit:state.portfolioAudit?{repoCount:state.portfolioAudit.repoCount,completedAt:state.portfolioAudit.completedAt}:null});state.projects.unshift(p);return p;}
function openOrCreateWorkProject(workKey){const p=ensureWorkProject(workKey);if(!p)return;currentProjectId=p.id;currentView='projects';currentProjectTab='bible';save();render();toast('作品工作区已打开');}
async function deepAnalyzeWork(workKey){const group=workGroups().find(g=>g.key===workKey),main=group?.repos?.find(x=>x.category==='game');if(!group||!main?.repo)return toast('请先指定并确认主游戏，再进行深度复盘');const p=ensureWorkProject(workKey);if(!p)return;toast('正在读取主仓入口、实际引用链并进行深度复盘…');try{const repoUrl=main.repoUrl||`https://github.com/${settings.githubOwner}/${main.repo}`;const r=await api('/api/github/analyze',{repoUrl,project:p,experiences:relevantExperiences(p)},'POST',{timeoutMs:600000});p.githubReview={repo:main.repo,repoUrl,text:r.text,snapshot:compactScan(r.snapshot||{}),analyzedAt:Date.now(),degraded:!!r.degraded,fallbackReason:r.fallbackReason||''};p.chat.push({role:'assistant',text:`【GitHub 实际引用复盘｜${main.repo}${r.degraded?'｜精简重试':''}】\n${r.text}`,ts:Date.now()});p.updatedAt=Date.now();updateCatalogFromScan(main.repo,r.snapshot||{});save();currentProjectId=p.id;currentView='studio';render();toast(r.degraded?'主仓复盘已通过精简证据重试完成，结果已写入项目':'主仓库深度复盘完成，结果已写入该项目');}catch(e){toast(`深度复盘失败：${e.message}`);}}

function compactScan(s){return{repository:s.repository,entries:(s.entries||[]).slice(0,12),referenced:(s.referenced||[]).slice(0,160),unreachableCount:s.unreachableCount,unreachableSample:(s.unreachableSample||[]).slice(0,24),filesRead:(s.filesRead||[]).slice(0,80),signals:s.signals,sample:String(s.sample||'').slice(0,7000),truncated:!!s.truncated};}
function savePortfolioCheckpoint(){if(!save())throw new Error('浏览器本地存储空间不足，扫描断点无法安全保存；请先导出项目备份或清理旧数据');}
function updatePortfolioProgress(message,phase='inspect'){const scan=state.portfolioScan;if(scan){scan.phase=phase;scan.message=message;scan.updatedAt=Date.now();savePortfolioCheckpoint();}const box=$('#portfolioProgress');if(box)box.innerHTML=portfolioProgressHtml();}
function resetPortfolioScan(){confirmDialog('清除扫描断点？','清除当前扫描断点？已完成的最终作品集总结不会删除。',()=>{state.portfolioScan=null;save();render();toast('扫描断点已清除');});}
function eligiblePortfolioRepos(repos=state.repoCache||[]){return repos.filter(r=>!r.archived&&!r.fork&&catalogEntry(r.name)?.category!=='tool');}
function sameRepoSet(a=[],b=[]){if(a.length!==b.length)return false;const A=[...a].sort(),B=[...b].sort();return A.every((x,i)=>x===B[i]);}
async function loadRepoList(force=false){try{if(!force&&state.repoCache?.length){ensureRepoCatalog();return state.repoCache;}const r=await api('/api/github/repos',{owner:settings.githubOwner});state.repoCache=r.repos||[];state.repoCatalog=mergeRepoCatalog(state.repoCache,state.repoCatalog||[]);let changed=false;if(force&&state.portfolioScan&&!state.portfolioScan.finished){const current=state.portfolioScan.repoNames||[],fresh=eligiblePortfolioRepos(state.repoCache).map(x=>x.name);changed=!sameRepoSet(current,fresh);if(changed){state.portfolioScan.message='检测到仓库集合变化；为避免丢失成果，当前扫描断点仍保留。完成当前总结后再手动重新扫描。';state.portfolioScan.updatedAt=Date.now();}}save();render();toast(`读取到 ${state.repoCache.length} 个公开仓库，已同步作品整理表${changed?'；旧扫描断点已保留':''}`);return state.repoCache;}catch(e){toast(e.message);return[];}}
async function inspectOneRepo(repo){try{return{name:repo.name,scan:compactScan(await apiRaw('/api/github/inspect',{owner:settings.githubOwner,repo:repo.name},'POST',{timeoutMs:45000}))};}catch(err){return{name:repo.name,error:err.message};}}
async function mapLimit(items,limit,fn){const out=new Array(items.length);let cursor=0;async function runner(){while(cursor<items.length){const i=cursor++;out[i]=await fn(items[i],i);}}await Promise.all(Array.from({length:Math.min(limit,items.length)},runner));return out;}
function fallbackBatchReview(results){const lines=results.map(x=>{if(x.error)return`${x.name}：扫描失败（${x.error}）`;const g=x.scan?.signals||{};return`${x.name}：可达文本 ${g.reachableTextFiles||0}，引用文件 ${g.referencedFiles||0}/${g.totalRepoFiles||0}，HTML ${g.htmlFiles||0}，CSS ${g.cssFiles||0}，图片 ${g.imageFiles||0}${g.hasLockedLanguage?'；存在章节/未解锁措辞':''}${g.hasAiCliche?'；命中高频AI恐怖套话':''}`;});return`【本批自动降级摘要｜AI 批次总结失败】\n${lines.join('\n')}\n后续总结合并时必须降低对此批次的置信度。`;}
function fallbackSynthesisPart(batchSlice,partIndex){return`【总结分片 ${partIndex+1}｜AI 降级】\n`+batchSlice.map((b,i)=>`批次 ${b.batchNo||i+1}（${(b.repos||[]).join('、')}）：\n${String(b.text||'').slice(0,2200)}`).join('\n\n');}
function fallbackPortfolioSynthesis(scan,repos,error=''){const parts=(scan.synthesisParts||[]).map((p,i)=>`分片 ${i+1}：${String(p.text||'').slice(0,1800)}`).join('\n\n');const failed=[...new Map((scan.errors||[]).map(x=>[x.repo,x])).values()].filter(x=>repos.some(r=>r.name===x.repo));return`【创作总结暂存版｜AI 最终合并未完成】\n已完成 ${repos.length} 个纳入扫描仓库的引用链检查与 ${scan.batches.length} 个批次复盘，原始扫描证据和断点均已保存，不需要重新扫描。\n\n${parts||'已有批次复盘已保存，可稍后仅重试 AI 创作总结。'}\n\n【证据缺口】\n${failed.length?failed.map(x=>`${x.repo}：${x.error}`).join('\n'):'未记录仓库级扫描失败。'}\n${error?`\n最终合并失败原因：${error}`:''}\n\n该暂存版只用于防止扫描成果丢失；点击“仅重试创作总结”可在不重扫仓库的情况下生成正式 AI 方法论总结。`;}
async function retryOnce(fn,onRetry){try{return await fn();}catch(e){onRetry?.(e);await new Promise(r=>setTimeout(r,1200));return fn();}}
async function buildSynthesisParts(scan){const reviews=(scan.batches||[]).map((b,i)=>({batchNo:i+1,repos:b.repos||[],fallback:!!b.fallback,text:String(b.text||'').slice(0,6500)})),groups=[];for(let i=0;i<reviews.length;i+=3)groups.push(reviews.slice(i,i+3));scan.synthesisParts=Array.isArray(scan.synthesisParts)?scan.synthesisParts:[];for(let i=0;i<groups.length;i++){if(scan.synthesisParts[i]?.text)continue;updatePortfolioProgress(`正在压缩创作总结证据 ${i+1}/${groups.length}…`,'synthesis');let text,fallback=false;try{const r=await retryOnce(()=>callAiRaw('portfolio_synthesis_chunk',{owner:settings.githubOwner,part:i+1,totalParts:groups.length,batchReviews:groups[i],scanErrors:scan.errors},{timeoutMs:115000}),()=>updatePortfolioProgress(`总结分片 ${i+1} 首次未完成，正在重试…`,'synthesis'));text=r.text;}catch(e){text=fallbackSynthesisPart(groups[i],i);fallback=true;scan.errors.push({repo:`总结分片 ${i+1}`,error:`AI总结分片失败：${e.message}`,at:Date.now()});}scan.synthesisParts[i]={index:i,reviews:groups[i].map(x=>x.batchNo),text,fallback,at:Date.now()};scan.updatedAt=Date.now();savePortfolioCheckpoint();}return scan.synthesisParts;}
async function finishPortfolioSynthesis(repos,scan,{forceFinal=false}={}){updatePortfolioProgress(`全部 ${repos.length} 个仓库已处理，正在分层合并跨作品方法论…`,'synthesis');if(forceFinal)scan.summaryError='';const parts=await buildSynthesisParts(scan);let final;try{final=await retryOnce(()=>callAiRaw('portfolio_synthesis',{owner:settings.githubOwner,repoCount:repos.length,workCount:workGroups().filter(g=>g.repos.some(x=>x.category==='game')).length,synthesisParts:parts.map((p,i)=>({part:i+1,fallback:!!p.fallback,text:String(p.text||'').slice(0,7000)})),scanErrors:scan.errors,portfolioAuditVersion:4},{timeoutMs:135000}),()=>updatePortfolioProgress('最终创作总结首次未完成，正在重试一次…','synthesis'));}catch(e){const summary=fallbackPortfolioSynthesis(scan,repos,e.message);state.portfolioAudit={owner:settings.githubOwner,repoCount:repos.length,workCount:workGroups().filter(g=>g.repos.some(x=>x.category==='game')).length,successCount:repos.length-new Set((scan.errors||[]).filter(x=>repos.some(r=>r.name===x.repo)).map(x=>x.repo)).size,failedCount:new Set((scan.errors||[]).filter(x=>repos.some(r=>r.name===x.repo)).map(x=>x.repo)).size,completedAt:Date.now(),batchCount:scan.batches.length,summary,summaryMode:'fallback',summaryError:e.message};scan.phase='done_warn';scan.finished=true;scan.summaryMode='fallback';scan.summaryError=e.message;scan.message='仓库扫描完成；AI 最终总结暂时使用降级版，可单独重试';scan.updatedAt=Date.now();for(const p of state.projects)p.portfolioAudit={repoCount:repos.length,completedAt:Date.now()};savePortfolioCheckpoint();render();toast('仓库扫描结果已完整保存；最终总结可稍后单独重试，无需重扫');return false;}
  state.portfolioAudit={owner:settings.githubOwner,repoCount:repos.length,workCount:workGroups().filter(g=>g.repos.some(x=>x.category==='game')).length,successCount:repos.length-new Set((scan.errors||[]).filter(x=>repos.some(r=>r.name===x.repo)).map(x=>x.repo)).size,failedCount:new Set((scan.errors||[]).filter(x=>repos.some(r=>r.name===x.repo)).map(x=>x.repo)).size,completedAt:Date.now(),batchCount:scan.batches.length,summary:final.text,summaryMode:'ai',summaryError:''};for(const p of state.projects)p.portfolioAudit={repoCount:repos.length,completedAt:Date.now()};scan.phase='done';scan.finished=true;scan.summaryMode='ai';scan.summaryError='';scan.message=`全量复盘完成，共 ${scan.batches.length} 批`;scan.updatedAt=Date.now();savePortfolioCheckpoint();render();toast('作品集全量复盘完成，已成为全局制作上下文');return true;}
async function retryPortfolioSummary(){const scan=normalizePortfolioScan(state.portfolioScan);if(!scan?.batches?.length)return toast('还没有已保存的扫描批次');const map=new Map((state.repoCache||[]).map(r=>[r.name,r])),repos=(scan.repoNames||[]).map(n=>map.get(n)).filter(Boolean);if(!repos.length)return toast('找不到原扫描对应的仓库列表');scan.finished=false;scan.phase='synthesis';state.portfolioScan=scan;setBusy(true);try{await finishPortfolioSynthesis(repos,scan,{forceFinal:true});}catch(e){scan.finished=true;scan.phase='done_warn';scan.summaryError=e.message;scan.message=`重试总结失败：${e.message}`;savePortfolioCheckpoint();render();toast(`仅重试总结失败：${e.message}`);}finally{setBusy(false);}}
async function scanPortfolio(){let allRepos=state.repoCache?.length?state.repoCache:await loadRepoList();ensureRepoCatalog();let scan=normalizePortfolioScan(state.portfolioScan),repoMap=new Map((allRepos||[]).map(r=>[r.name,r])),repos;const canResume=scan&&!scan.finished&&scan.owner===settings.githubOwner&&(scan.repoNames||[]).length&&(scan.repoNames||[]).every(n=>repoMap.has(n));if(canResume)repos=scan.repoNames.map(n=>repoMap.get(n));else repos=eligiblePortfolioRepos(allRepos);if(!repos.length)return;portfolioStopRequested=false;const names=repos.map(r=>r.name);const compatible=canResume||!!(scan&&scan.owner===settings.githubOwner&&sameRepoSet(scan.repoNames,names)&&!scan.finished);if(!compatible){scan=normalizePortfolioScan({owner:settings.githubOwner,repoNames:names,batches:[],pending:[],errors:[],synthesisParts:[],phase:'inspect',startedAt:Date.now(),updatedAt:Date.now(),finished:false,message:'准备开始'});state.portfolioScan=scan;savePortfolioCheckpoint();}
  try{
    while(true){const processed=portfolioProcessed(scan),remaining=repos.filter(r=>!processed.has(r.name));if(!remaining.length&&!(scan.pending||[]).length)break;
      const pending=scan.pending||[];const need=Math.max(0,6-pending.length);const todo=remaining.slice(0,need);if(todo.length){const baseDone=processed.size;updatePortfolioProgress(`${baseDone+1}-${Math.min(repos.length,baseDone+todo.length)}/${repos.length} 正在并行检查：${todo.map(x=>x.name).join('、')}`,'inspect');const results=await mapLimit(todo,Math.min(3,todo.length),r=>inspectOneRepo(r));for(const result of results){pending.push(result);if(result.scan)updateCatalogFromScan(result.name,result.scan);if(result.error)scan.errors.push({repo:result.name,error:result.error,at:Date.now()});scan.pending=pending;scan.updatedAt=Date.now();savePortfolioCheckpoint();}}
      if(portfolioStopRequested){scan.phase='paused';scan.message=`已保存 ${portfolioProcessed(scan).size}/${repos.length} 的断点`;scan.updatedAt=Date.now();savePortfolioCheckpoint();render();toast('已暂停，可稍后继续');return;}
      if(!pending.length)break;
      const batchNames=pending.map(x=>x.name);updatePortfolioProgress(`✓ ${batchNames.join('、')} 引用链检查完成。正在总结第 ${scan.batches.length+1} 批（${batchNames.length} 个仓库）…`,'review');let text;try{const review=await retryOnce(()=>callAiRaw('portfolio_batch_review',{owner:settings.githubOwner,repositories:pending.map(x=>x.error?{repository:{repo:x.name},catalogRole:catalogEntry(x.name)?.category||'unknown',error:x.error}:{...x.scan,catalogRole:catalogEntry(x.name)?.category||'unknown'}),portfolioAuditVersion:4},{timeoutMs:120000}),()=>updatePortfolioProgress(`AI 批次总结首次未完成，正在重试一次…`,'review'));text=review.text;}catch(e){text=fallbackBatchReview(pending);scan.errors.push({repo:`批次 ${scan.batches.length+1}`,error:`AI总结失败：${e.message}`,at:Date.now()});}
      scan.batches.push({repos:batchNames,text,at:Date.now(),fallback:text.startsWith('【本批自动降级摘要')});scan.pending=[];scan.synthesisParts=[];scan.updatedAt=Date.now();scan.message=`第 ${scan.batches.length} 批已保存`;savePortfolioCheckpoint();if(portfolioStopRequested){scan.phase='paused';savePortfolioCheckpoint();render();toast('已暂停，可稍后继续');return;}
    }
    await finishPortfolioSynthesis(repos,scan);
  }catch(e){scan.phase='error';scan.message=e.message;scan.updatedAt=Date.now();savePortfolioCheckpoint();render();toast(`扫描已保存断点：${e.message}`);}}

function studioTaskLabel(task){return({project_blueprint:'完整项目策划',virtual_player:'虚拟玩家测试',anti_ai_review:'AI 味审查',story_bible:'故事圣经',page_architecture:'页面架构',puzzle_design:'谜题设计',copy_pack:'完整文案',visual_direction:'视觉方向',image_direction:'图片设计',release_plan:'发布检查',director_chat:'导演对话',github_analyze:'单仓实际引用复盘'})[task]||task;}
function setStudioStatus(message,state='working'){const box=$('#studioStatus'),text=$('#studioStatusText');if(!box||!text)return;box.classList.remove('working','done','error');if(state)box.classList.add(state);text.textContent=message;const cb=$('#cancelStudioTask');if(cb)cb.style.display=state==='working'?'inline-block':'none';}
let studioTicker=null;function clearStudioTicker(){if(studioTicker){clearInterval(studioTicker);studioTicker=null;}}
let studioRun=null;function startStudioRun(label){if(studioRun){try{studioRun.controller.abort();}catch{}}const controller=new AbortController();studioRun={controller,label};return controller.signal;}function clearStudioRun(signal){if(!signal||(studioRun&&studioRun.controller===signal))studioRun=null;}function cancelStudioRun(){if(!studioRun)return;const ctrl=studioRun.controller;setStudioStatus('正在取消当前任务…','working');if(ctrl)ctrl.abort();}
function startStudioTicker(label,timeoutMs){const started=Date.now(),limit=Number(timeoutMs)||300000;clearStudioTicker();studioTicker=setInterval(()=>{const el=Date.now()-started,remain=Math.max(0,limit-el);setStudioStatus(`正在运行「${label}」… 已耗时 ${fmtDuration(el)} · 预计剩余 ${fmtDuration(remain)}`,'working');},1000);}
function scrollStudioOutput(){setTimeout(()=>{const box=$('#messages');if(!box)return;box.scrollTop=box.scrollHeight;box.lastElementChild?.scrollIntoView({behavior:'smooth',block:'nearest'});},0);}
async function runStudioTask(task){const p=activeProject();if(!p)return;const label=studioTaskLabel(task),signal=startStudioRun(label);setStudioStatus(`正在运行「${label}」…`, 'working');startStudioTicker(label,aiCallOptions(task).timeoutMs);toast(`正在运行：${label}`);try{const r=await callAi(task,await studioTaskPayload(task,signal),{signal});p.chat.push({role:'assistant',text:`【${label}】\n【模型 ${r.model||'未记录'}${r.routeTier?` · ${String(r.routeTier).toUpperCase()}`:''}${r.fallbackUsed?' · 已回退':''}】\n${r.text}`,ts:Date.now()});save();render();setStudioStatus(`「${label}」已完成，结果已写入下方记录。`,'done');scrollStudioOutput();}catch(e){if(e?.code==='CANCELLED'||/取消|已取消/.test(String(e?.message||''))){setStudioStatus(`「${label}」已取消。`,'done');toast(`${label}已取消`);}else{setStudioStatus(`「${label}」失败：${e.message}`,'error');toast(`${label}失败：${e.message}`);}}finally{clearStudioTicker();clearStudioRun(signal);}}
async function sendChat(){const p=activeProject(),input=$('#chatInput'),text=input?.value.trim();if(!p||!text)return;const signal=startStudioRun('导演对话');p.chat.push({role:'user',text,ts:Date.now()});save();render();setStudioStatus('制作总监正在回复…','working');startStudioTicker('导演对话',aiCallOptions('director_chat').timeoutMs);scrollStudioOutput();try{const r=await callAi('director_chat',{message:text,...taskPayload(p),history:p.chat.slice(-10)},{signal});p.chat.push({role:'assistant',text:`【模型 ${r.model||'未记录'}${r.routeTier?` · ${String(r.routeTier).toUpperCase()}`:''}${r.fallbackUsed?' · 已回退':''}】\n${r.text}`,ts:Date.now()});save();render();setStudioStatus('回复完成。','done');scrollStudioOutput();}catch(e){if(e?.code==='CANCELLED'||/取消|已取消/.test(String(e?.message||''))){setStudioStatus('回复已取消。','done');toast('已取消');}else{setStudioStatus(`回复失败：${e.message}`,'error');toast(e.message);}}finally{clearStudioTicker();clearStudioRun(signal);}}
function githubAnalyzePrompt(){showModal('复盘 GitHub 公开仓库',`<div class="field"><label>仓库地址</label><input id="repoUrl" placeholder="https://github.com/${escapeHtml(settings.githubOwner)}/xu-yuan"></div><p class="tiny muted">从入口文件追踪实际引用依赖；未引用文件只作为疑似残留提示。</p>`,()=>{const url=$('#repoUrl').value.trim();if(!url)return;closeModal();githubAnalyze(url);});}
async function githubAnalyze(url){const p=activeProject();const signal=startStudioRun('单仓实际引用复盘');toast('正在追踪仓库入口与实际引用文件…');setStudioStatus('正在追踪仓库入口与实际引用文件…','working');startStudioTicker('单仓实际引用复盘',600000);try{const r=await api('/api/github/analyze',{repoUrl:url,project:p,experiences:relevantExperiences(p||{genres:[]})},'POST',{timeoutMs:600000,signal});if(p){p.chat.push({role:'assistant',text:`【单仓实际引用复盘】\n${r.text}`,ts:Date.now()});save();currentView='studio';render();setStudioStatus('单仓实际引用复盘完成，结果已写入下方记录。','done');scrollStudioOutput();toast('单仓实际引用复盘完成');}}catch(e){if(e?.code==='CANCELLED'||/取消|已取消/.test(String(e?.message||''))){setStudioStatus('单仓复盘已取消。','done');toast('已取消');}else{setStudioStatus(`单仓复盘失败：${e.message}`,'error');toast(`单仓复盘失败：${e.message}`);}}finally{clearStudioTicker();clearStudioRun(signal);}}

async function runBlindReview(){const p=activeProject(),repoUrl=$('#blindRepoUrl')?.value.trim();if(!p||!repoUrl)return toast('先填写主游戏 GitHub 仓库地址');const verify=$('#blindVerify')?.checked!==false,mode=$('#blindMode')?.value==='manual'?'manual':'auto',useExp=$('#blindExperience')?.checked===true;const expCtx=useExp?relevantExperiences(p).map(x=>({title:String(x.title||'').slice(0,60),body:String(x.body||'').slice(0,180),category:String(x.category||''),scope:String(x.scope||'')})).slice(0,8):[];const moduleIds=[...document.querySelectorAll('[data-blind-mod]')].filter(el=>el.checked).map(el=>el.dataset.blindMod);const activeMods=moduleIds.length?BLIND_MODULES.filter(x=>moduleIds.includes(x.id)):BLIND_MODULES;if(!activeMods.length)return toast('至少勾选一个盲审模块');p.blindRepoUrl=repoUrl;save();let task;try{task=beginBlindTask(verify,mode,activeMods.map(x=>x.id));}catch(e){return toast(e.message);}const identity={title:p.title,genres:(p.genres||[]).map(x=>x.id)},requestedRoute={mode:settings.aiMode||'auto',provider:settings.aiMode==='fixed'?(settings.aiProvider||'cloudflare'):'',model:''},perf={startedAt:Date.now(),prepareMs:0,modulesMs:0,moduleMs:{},moduleAttempts:{},mergeMs:0,verifyMs:0,totalMs:0};let draftRun=null,draftPersisted=false,prep=null,moduleRunsCompleted=[],moduleErrors=[];toast(verify?'盲复盘已开始：仓库取证 → 模块盲审 → 本地合并 → 复核':'快速盲复盘已开始：仓库取证 → 模块盲审 → 本地合并');try{
  setBlindTaskStage(0,'正在追踪入口与实际引用文件');let t=Date.now();prep=await apiRaw('/api/review/blind/prepare',{repoUrl},'POST',{timeoutMs:180000,signal:task.controller.signal});perf.prepareMs=prep.elapsedMs||Date.now()-t;
  if(mode==='manual')await waitBlindContinue(`仓库取证完成：读取 ${prep.evidence?.filesRead||0} 个文本文件`);setBlindTaskStage(1,`已读取 ${prep.evidence?.filesRead||0} 个文本文件；开始并发模块审查（超时会自动精简证据重试）`);const moduleStarted=Date.now();const runOneModule=async def=>{if(task.controller.signal.aborted)throw Object.assign(new Error('操作已取消'),{code:'CANCELLED'});setBlindModule(def.id,'running');const mt=Date.now();let firstError='';try{const r=await apiRaw('/api/review/blind/module',{snapshot:prep.snapshot,identity,module:def.id,compact:false,experience:expCtx},'POST',{timeoutMs:300000,signal:task.controller.signal});const elapsed=Date.now()-mt;perf.moduleMs[def.id]=elapsed;perf.moduleAttempts[def.id]=1;setBlindModule(def.id,'done',{elapsedMs:elapsed,fallback:false,review:r.review});const out={module:def.id,label:def.label,review:r.review||{},model:r.model||'',plannedModel:r.plannedModel||'',routeMode:r.routeMode||'',routeTier:r.routeTier||'',fallbackUsed:!!r.fallbackUsed,fallback:false};moduleRunsCompleted.push(out);return out;}catch(e){if(task.controller.signal.aborted)throw e;firstError=e.message;if(!shouldRetryBlindModuleError(e)){const elapsed=Date.now()-mt;perf.moduleMs[def.id]=elapsed;perf.moduleAttempts[def.id]=1;moduleErrors.push({module:def.id,label:def.label,error:firstError});setBlindModule(def.id,'error',{elapsedMs:elapsed,error:firstError});return null;}setBlindModule(def.id,'retrying',{error:firstError});}
    try{const r=await apiRaw('/api/review/blind/module',{snapshot:prep.snapshot,identity,module:def.id,compact:true,experience:expCtx},'POST',{timeoutMs:240000,signal:task.controller.signal});const elapsed=Date.now()-mt;perf.moduleMs[def.id]=elapsed;perf.moduleAttempts[def.id]=2;setBlindModule(def.id,'done',{elapsedMs:elapsed,fallback:true,review:r.review});const out={module:def.id,label:def.label,review:r.review||{},model:r.model||'',plannedModel:r.plannedModel||'',routeMode:r.routeMode||'',routeTier:r.routeTier||'',fallbackUsed:!!r.fallbackUsed,fallback:true};moduleRunsCompleted.push(out);return out;}catch(e2){const elapsed=Date.now()-mt;perf.moduleMs[def.id]=elapsed;perf.moduleAttempts[def.id]=2;if(task.controller.signal.aborted)throw e2;const err=`初审：${firstError}；精简重试：${e2.message}`;moduleErrors.push({module:def.id,label:def.label,error:err});setBlindModule(def.id,'error',{elapsedMs:elapsed,error:err});return null;}};let moduleRuns;if(mode==='manual'){moduleRuns=[];for(const def of activeMods){const r=await runOneModule(def);moduleRuns.push(r);if(r)await waitBlindContinue(`${def.label} 完成：评分 ${r.review?.score==null?'—':Number(r.review.score).toFixed(1)+'/10'} · ${(r.review?.findings||[]).length} 个问题`);}}else{moduleRuns=await mapLimit(activeMods,Math.min(4,activeMods.length),runOneModule);}perf.modulesMs=Date.now()-moduleStarted;const completed=moduleRuns.filter(Boolean);if(!completed.length)throw new Error('所选盲审模块在自动重试后仍均未完成，请稍后重试或检查 Workers AI 状态');
  setBlindTaskStage(2,`已完成 ${completed.length}/${activeMods.length} 个模块，正在本地合并与去重证据（不再额外等待一次 AI 合并）`);t=Date.now();const merged=mergeBlindModulesLocal(completed,prep.evidence,moduleErrors),mergeMode='local-fast',mergeError='';perf.mergeMs=Date.now()-t;if(mode==='manual')await waitBlindContinue(`本地合并完成：${merged.findings?.length||0} 个聚类问题`);
  let zeroChallenged=false,zeroChallengeError='';if((merged.findings||[]).length===0&&!moduleErrors.length&&!task.controller.signal.aborted){setBlindTaskStage(2,'模块合并为 0 个问题，正在做零结果反证检查');try{const z=await apiRaw('/api/review/blind/zero-challenge',{snapshot:prep.snapshot,identity,draft:merged,experience:expCtx},'POST',{timeoutMs:300000,signal:task.controller.signal});zeroChallenged=true;if(z.review?.findings?.length){merged.findings=z.review.findings;merged.summary=z.review.summary||merged.summary;merged.blindSpots=[...(merged.blindSpots||[]),...(z.review.blindSpots||[])].slice(0,16);if(z.review.confidence>merged.confidence)merged.confidence=z.review.confidence;}if(z.model)completed.push({module:'zero_challenge',label:'零结果反证检查',review:z.review||{},model:z.model,plannedModel:z.plannedModel||'',routeMode:z.routeMode||'',routeTier:z.routeTier||'',fallbackUsed:!!z.fallbackUsed,fallback:false});}catch(e){if(task.controller.signal.aborted)throw e;zeroChallengeError=e.message;merged.blindSpots=[...(merged.blindSpots||[]),`零结果反证检查未完成：${e.message}`].slice(0,16);}}
  const models=[...new Set(completed.map(x=>x.model).filter(Boolean))];draftRun={id:uid('blind'),createdAt:Date.now(),model:models.join(' / '),requestedRoute,moduleTotal:activeMods.length,experienceMode:useExp,zeroChallenged,zeroChallengeError,ruleVersion:'blind-v1.4-reliable',verified:false,verifyError:verify?'二次证据复核尚未完成':'',evidence:prep.evidence||{},result:merged,judgments:{},moduleErrors,moduleSummary:completed.map(x=>({module:x.module,label:x.label,score:x.review?.score??null,confidence:x.review?.confidence??0,summary:String(x.review?.summary||'').slice(0,500),fallback:!!x.fallback,attempts:perf.moduleAttempts[x.module]||1})),mergeMode,mergeError,performance:{...perf,totalMs:Date.now()-perf.startedAt}};p.blindReviews=Array.isArray(p.blindReviews)?p.blindReviews:[];p.blindReviews.unshift(draftRun);p.blindReviews=p.blindReviews.slice(0,20);blindSelectedRunId=draftRun.id;if(!save())throw new Error('本地存储空间不足，无法保存模块盲审结果');draftPersisted=true;
  if(verify&&!task.controller.signal.aborted){setBlindTaskStage(3,`已本地合并 ${draftRun.result?.findings?.length||0} 个聚类问题，正在做短版证据复核`);t=Date.now();try{const second=await apiRaw('/api/review/blind/verify',{snapshot:prep.snapshot,identity,draft:draftRun.result,experience:expCtx},'POST',{timeoutMs:300000,signal:task.controller.signal});perf.verifyMs=second.elapsedMs||Date.now()-t;draftRun.result=second.review||draftRun.result;draftRun.verified=true;draftRun.verifyError='';if(second.model&&!draftRun.model.includes(second.model))draftRun.model=`${draftRun.model} / ${second.model}`;if(mode==='manual')await waitBlindContinue('二次证据复核完成');}catch(e){perf.verifyMs=Date.now()-t;if(task.controller.signal.aborted){draftRun.verifyError='用户取消二次证据复核；已保留模块汇总结果';}else{draftRun.verifyError=`二次证据复核未完成：${e.message}`;}draftRun.verified=false;}}
  setBlindTaskStage(task.stages.length-1,'正在保存测试记录');draftRun.performance={...perf,totalMs:Date.now()-perf.startedAt};if(!save())throw new Error('本地存储空间不足，最终记录未能保存');render();setTimeout(()=>$('#blindSelectedSummary')?.scrollIntoView({behavior:'smooth',block:'start'}),0);endBlindTask(task.controller.signal.aborted?'cancelled':'done',task.controller.signal.aborted?'已取消后续步骤；已保存完成模块结果':draftRun.verified?'自适应模块盲审与证据复核完成':`${completed.length}/${activeMods.length} 个模块结果已保存`);toast(`盲复盘已记录：${draftRun.result?.findings?.length||0} 个聚类问题 · 模块 ${completed.length}/${activeMods.length}${completed.some(x=>x.fallback)?' · 含自动精简重试':''}${draftRun.verified?' · 已双重复核':moduleErrors.length?' · 部分模块未完成':''}${task.controller.signal.aborted?' · 后续已取消':''}`);
}catch(e){if(draftRun&&draftPersisted){draftRun.performance={...perf,totalMs:Date.now()-perf.startedAt};draftRun.verifyError=draftRun.verifyError||`任务中断：${e.message}`;save();render();endBlindTask('error','任务中断，但已完成模块结果已经保存');toast('任务已中断；已完成的盲复盘结果已保留');}else if(moduleRunsCompleted.length&&prep?.evidence){const partial=mergeBlindModulesLocal(moduleRunsCompleted,prep.evidence,moduleErrors);draftRun={id:uid('blind'),createdAt:Date.now(),model:[...new Set(moduleRunsCompleted.map(x=>x.model).filter(Boolean))].join(' / '),requestedRoute,moduleTotal:activeMods.length,experienceMode:useExp,incomplete:true,ruleVersion:'blind-v1.4-reliable',verified:false,verifyError:`任务中断：${e.message}`,evidence:prep.evidence,result:partial,judgments:{},moduleErrors,moduleSummary:moduleRunsCompleted.map(x=>({module:x.module,label:x.label,score:x.review?.score??null,confidence:x.review?.confidence??0,summary:String(x.review?.summary||'').slice(0,500),fallback:!!x.fallback,attempts:perf.moduleAttempts[x.module]||1})),mergeMode:'partial-local',mergeError:e.message,performance:{...perf,totalMs:Date.now()-perf.startedAt}};p.blindReviews=Array.isArray(p.blindReviews)?p.blindReviews:[];p.blindReviews.unshift(draftRun);p.blindReviews=p.blindReviews.slice(0,20);blindSelectedRunId=draftRun.id;save();render();endBlindTask(task?.controller?.signal?.aborted?'cancelled':'error',`任务中断；已保存 ${moduleRunsCompleted.length}/${activeMods.length} 个完成模块`);toast(`任务中断；已保存 ${moduleRunsCompleted.length}/${activeMods.length} 个模块的部分结果`);}else{endBlindTask(task?.controller?.signal?.aborted?'cancelled':'error',task?.controller?.signal?.aborted?'已取消；尚未形成可保存的模块结果':e.message);toast(task?.controller?.signal?.aborted?'盲复盘已取消':`盲复盘失败：${e.message}`);}}
}
function setBlindVerdict(runId,index,value){const p=activeProject(),run=(p?.blindReviews||[]).find(x=>x.id===runId);if(!run)return;run.judgments=run.judgments||{};if(value)run.judgments[index]=value;else delete run.judgments[index];save();render();}
function viewBlindReview(runId){const p=activeProject();if(!(p?.blindReviews||[]).some(x=>x.id===runId))return;blindSelectedRunId=runId;render();setTimeout(()=>$('#blindSelectedSummary')?.scrollIntoView({behavior:'smooth',block:'start'}),0);}
function deleteBlindReview(runId){const p=activeProject(),run=(p?.blindReviews||[]).find(x=>x.id===runId);if(!p||!run)return;confirmDialog('删除这条盲复盘记录？',`${new Date(run.createdAt).toLocaleString()} · ${(run.evidence?.revision||'无修订信息').slice(0,12)}\n\n删除只移除这条测试记录，不影响项目、普通 QA 或作品内容。`,()=>{p.blindReviews=p.blindReviews.filter(x=>x.id!==runId);if(blindSelectedRunId===runId)blindSelectedRunId=p.blindReviews[0]?.id||null;save();render();toast('已删除这条盲复盘记录');});}
function clearBlindReviews(){const p=activeProject();if(!p?.blindReviews?.length)return;confirmDialog('清空盲复盘历史？','清空当前项目的全部盲复盘历史？这不会删除普通 QA、项目内容或作品集数据。',()=>{p.blindReviews=[];blindSelectedRunId=null;save();render();toast('盲复盘历史已清空');});}

async function runAiQa(){const p=activeProject();if(!p)return;saveProjectEditor();const signal=startStudioRun('证据制独立评审');toast('正在运行证据制独立评审…');try{const r=await api('/api/review',{project:p,experiences:relevantExperiences(p),portfolioAudit:portfolioContext()},'POST',{timeoutMs:300000,signal});p.review={...r.review,model:r.model||'',plannedModel:r.plannedModel||'',routeTier:r.routeTier||'',routeMode:r.routeMode||settings.aiMode||'',fallbackUsed:!!r.fallbackUsed,ruleVersion:r.ruleVersion||'strict-v2',reviewedAt:Date.now(),degraded:!!r.degraded,fallbackReason:r.fallbackReason||''};save();render();toast(r.degraded?'独立评审已用精简证据自动重试完成；建议关注证据覆盖说明':r.review?.score==null?'材料不足，评审没有强行给分':`独立评分 ${Number(r.review.score).toFixed(2)}/10`);}catch(e){if(e?.code==='CANCELLED'||/取消|已取消/.test(String(e?.message||''))){toast('独立评审已取消');}else toast(`独立评审失败：${e.message}`);}finally{clearStudioRun(signal);}}
function saveLocalQa(){const p=activeProject();p.qa=`本地硬检查｜${new Date().toLocaleString()}\n\n`+localQa(p).map(i=>`${i.severity} ${i.title}\n${i.detail}`).join('\n\n');p.updatedAt=Date.now();save();render();toast('本地 QA 已保存；这不是质量评分');}
async function runSiteAudit(){const p=activeProject(),url=$('#siteAuditUrl')?.value.trim();if(!p||!url)return toast('先填写 GitHub Pages 部署地址');toast('正在巡检部署页面、资源与静态交互信号…');try{const r=await api('/api/site/audit',{url});p.deployUrl=url;p.siteAudit=r;p.updatedAt=Date.now();save();render();toast(r.broken?.length?`部署巡检发现 ${r.broken.length} 个 HTTP 问题`:'部署巡检未发现 HTTP 断链');}catch(e){toast(`部署巡检失败：${e.message}`);}}

function workerBase(){return settings.workerUrl.replace(/\/$/,'');}
async function apiRaw(path,body=null,method='POST',options={}){if(!workerBase())throw new Error('还没有配置 Cloudflare Worker URL');const headers={'content-type':'application/json',...aiRoutingHeaders()};if(settings.appKey)headers['x-agent-key']=settings.appKey;const timeoutMs=Number(options.timeoutMs||300000),controller=new AbortController();let timedOut=false;const timer=setTimeout(()=>{timedOut=true;controller.abort();},timeoutMs),external=options.signal,onAbort=()=>controller.abort();if(external){if(external.aborted)controller.abort();else external.addEventListener('abort',onAbort,{once:true});}let res;try{res=await fetch(workerBase()+path,{method,headers,body:body?JSON.stringify(body):undefined,signal:controller.signal});}catch(e){if(e?.name==='AbortError'){if(external?.aborted&&!timedOut){const err=new Error('操作已取消');err.code='CANCELLED';throw err;}throw new Error(`请求超过 ${Math.round(timeoutMs/1000)} 秒，已自动中止`);}if(e instanceof TypeError)throw new Error('无法连接 Cloudflare Worker（网络中断、Worker 重启或 CORS/临时网关错误）；已保存的扫描断点不会丢失');throw e;}finally{clearTimeout(timer);external?.removeEventListener?.('abort',onAbort);}const text=await res.text();let data;try{data=JSON.parse(text);}catch{data={error:text};}if(!res.ok)throw new Error(data.error||`Worker 返回 ${res.status}`);return data;}
async function api(path,body=null,method='POST',options={}){if(busyDepth>0){const e=new Error('已有后台任务正在执行，请等待当前任务结束或取消后再试');e.code='BUSY';throw e;}setBusy(true);try{return await apiRaw(path,body,method,options);}finally{setBusy(false);}}
const AI_CLIENT_TIMEOUTS={project_blueprint:240000,virtual_player:180000,anti_ai_review:180000,story_bible:240000,page_architecture:240000,puzzle_design:240000,visual_direction:180000,image_direction:150000,release_plan:180000,director_chat:180000,copy_pack:300000,portfolio_batch_review:180000,portfolio_synthesis_chunk:180000,portfolio_synthesis:240000};
function aiCallOptions(task,options={}){return{...options,timeoutMs:Number(options.timeoutMs||AI_CLIENT_TIMEOUTS[task]||300000)};}
async function callAiRaw(task,payload,options={}){return apiRaw('/api/ai',{task,payload},'POST',aiCallOptions(task,options));}
async function callAi(task,payload,options={}){return api('/api/ai',{task,payload},'POST',aiCallOptions(task,options));}
async function testWorker(){try{if(!workerBase())throw new Error('请先填写 Worker URL');setBusy(true);const headers={...aiRoutingHeaders()};if(settings.appKey)headers['x-agent-key']=settings.appKey;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);let r;try{r=await fetch(workerBase()+'/api/ping',{headers,signal:controller.signal});}finally{clearTimeout(timer);}let j={};try{j=await r.json();}catch{}if(r.status===401)throw new Error('Agent Key 与 Cloudflare 的 APP_SECRET 不一致');if(!r.ok)throw new Error(j.error||'连接失败');if(!j.textReady)throw new Error(j.textError||`Worker 已连接，但当前模型策略尚未配置完整`);$('#workerDot').classList.add('live');const route=j.requestRoute||{},routeText=route.provider?`${route.provider} · ${route.model}`:`${j.provider||'AI'} · ${j.model||'未记录模型'}`;$('#workerLabel').textContent=`AI 已连接 · ${modelStrategyLabel()} · ${routeText}`;const imageNote=j.imageReady?'图片 AI 正常':'图片 AI 未绑定（仅影响图片生成）',fallbackNote=j.fallbackProvider?(j.fallbackReady?`；备用 ${j.fallbackProvider} 已就绪`:`；备用 ${j.fallbackProvider} 未就绪`):'',slotNote=settings.aiMode==='auto'&&j.slots?`；FAST ${j.slots.fast?.provider||'-'} / STANDARD ${j.slots.standard?.provider||'-'} / STRONG ${j.slots.strong?.provider||'-'}`:'';toast(j.github?`文本 AI、GitHub 正常；${imageNote}${slotNote}${fallbackNote}`:`文本 AI 正常，但尚未检测到 GITHUB_TOKEN；${imageNote}${slotNote}${fallbackNote}`);}catch(e){$('#workerDot').classList.remove('live');$('#workerLabel').textContent='AI 未连接';toast(e?.name==='AbortError'?'Worker 连接测试超时':e.message);}finally{setBusy(false);}}
async function saveAndTestSettings(){settings.workerUrl=$('#workerUrl').value.trim();settings.appKey=$('#appKey').value.trim();settings.githubOwner=$('#githubOwner').value.trim()||'Mike798-cloud';const m=$('[data-ai-mode-control]'),p=$('[data-ai-provider-control]');if(m)settings.aiMode=m.value;if(p)settings.aiProvider=p.value;saveSettings();await testWorker();}

async function openImageDb(){return new Promise((resolve,reject)=>{const q=indexedDB.open('narrative-agent-assets',1);q.onupgradeneeded=()=>q.result.createObjectStore('images');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
async function storeImage(projectId,dataURI){const db=await openImageDb();return new Promise((resolve,reject)=>{const tx=db.transaction('images','readwrite');tx.objectStore('images').put(dataURI,projectId);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function getImage(projectId){const db=await openImageDb();return new Promise((resolve,reject)=>{const q=db.transaction('images').objectStore('images').get(projectId);q.onsuccess=()=>resolve(q.result||'');q.onerror=()=>reject(q.error);});}
async function generateImage(){const p=activeProject(),prompt=$('#projectEditor')?.value.trim()||p?.imagePrompt;if(!p||!prompt)return toast('先完成图片设计说明');toast('正在生成图片并保存到浏览器资产库…');try{const r=await api('/api/image',{prompt,project:{title:p.title,concept:p.concept,genres:p.genres}});p.lastImage=r.dataURI;p.imageGeneratedAt=Date.now();p.updatedAt=Date.now();save();await storeImage(p.id,r.dataURI);$('#imageArea').innerHTML=`<img class="image-preview" src="${r.dataURI}" alt="生成图片预览">`;toast('图片已保存到浏览器资产库，刷新后仍可恢复');}catch(e){toast(e.message);}}
async function hydrateVisibleImage(){const p=activeProject(),area=$('#imageArea');if(!p||!area||p.lastImage)return;try{const img=await getImage(p.id);if(img){p.lastImage=img;area.innerHTML=`<img class="image-preview" src="${img}" alt="生成图片预览">`;}}catch{}}

function exportData(){const blob=new Blob([JSON.stringify({state:serializableState(),settings:{...settings,appKey:''},exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`narrative-agent-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);}
async function importData(ev){const f=ev.target.files?.[0];if(!f)return;try{const obj=JSON.parse(await f.text());if(!obj.state?.projects||!obj.state?.experiences)throw new Error('不是有效备份');state=obj.state;state.projects.forEach(normalizeProject);const known=new Set(state.experiences.map(x=>x.id));for(const seed of EXPERIENCE_SEED)if(!known.has(seed.id))state.experiences.push(clone(seed));state.portfolioAudit=state.portfolioAudit||null;state.portfolioScan=normalizePortfolioScan(state.portfolioScan);state.repoCache=state.repoCache||[];state.repoCatalog=mergeRepoCatalog(state.repoCache,state.repoCatalog||[]);currentProjectId=state.projects[0]?.id||null;save();render();toast('数据已导入');}catch(e){toast(e.message);}}
function resetAll(){confirmDialog('重置全部数据？','恢复初始经验库并重置所有项目？此操作不可撤销。',()=>{localStorage.removeItem(STORAGE_KEY);localStorage.removeItem('narrative_agent_state_v1');state=loadState();currentProjectId=state.projects[0]?.id;render();});}

$('#nav').addEventListener('click',e=>{const b=e.target.closest('button[data-view]');if(!b)return;currentView=b.dataset.view;render();});
$('#newProjectBtn').onclick=()=>openProjectModal();$('#exportBtn').onclick=exportData;render();if(workerBase())testWorker();
